
/* v29 fix: slug global para exportar JSON/certificados sin romper la descarga */
function slug(value){
  return String(value || 'archivo')
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase().replace(/[^a-z0-9]+/g,'-')
    .replace(/^-+|-+$/g,'') || 'archivo';
}



