/* v17 · Curaduría infantil 8-12: menos clase, más asombro y datos para contar.
   Reglas: no asumir saber previo; no usar subcápsulas genéricas; evitar que un mundo herede datos de otro. */
(function curateAtlasForChildrenV17(){
  if(typeof CAPSULES==='undefined' || typeof WORLDS==='undefined') return;
  const clean = s => String(s||'').replace(/\s+/g,' ').trim();
  const topic = t => clean(t).replace(/^(El|La|Los|Las|Un|Una)\s+/i,'').replace(/\.$/,'');
  const lead = fact => clean(fact).split(/(?<=[.!?])\s+/)[0] || clean(fact);
  const softer = fact => lead(fact)
    .replace(/resiliencia/gi,'capacidad de recuperarse')
    .replace(/tectónicas/gi,'tectónicas (placas enormes de roca que se mueven muy despacio)')
    .replace(/salinidad/gi,'cantidad de sal')
    .replace(/pH/gi,'pH (medida de acidez)')
    .replace(/diferenciarse/gi,'convertirse en tipos distintos')
    .replace(/polímeros/gi,'polímeros (cadenas larguísimas de moléculas)')
    .replace(/compuestos iónicos/gi,'compuestos formados por partículas con carga')
    .replace(/patrimonio inmaterial/gi,'tradiciones, músicas, fiestas o saberes que no se guardan como objetos');

  const exact = [
    [/sol es una estrella/i, {s:'Aunque parece una bolita en el cielo, el Sol concentra casi toda la masa del sistema solar: cerca del 99,86%.', subs:[['☀️','Gigante cercano','Dentro del Sol cabrían más de un millón de planetas Tierra.'],['⏱️','Luz en viaje','La luz solar tarda unos 8 minutos en llegar hasta nosotros.']]}],
    [/mercurio/i, {s:'Mercurio vive extremos: sin una gran “manta” de aire, el día puede quemar y la noche puede congelar.', subs:[['🌗','Sin manta de aire','Su atmósfera es muy delgada, por eso no guarda bien el calor.'],['🔥','No es el más caliente','Venus, aunque está más lejos del Sol, supera a Mercurio por su atmósfera espesa.']]}],
    [/venus/i, {s:'Venus es raro: gira tan lento que allí un día dura más que un año.', subs:[['🔄','Giro al revés','Venus rota en sentido contrario al de la mayoría de planetas.'],['🌫️','Calor atrapado','Su atmósfera espesa atrapa calor y lo vuelve el planeta más caliente.']]}],
    [/tierra es un planeta rocoso/i, {s:'La Tierra no es especial por una sola cosa: combina agua líquida, atmósfera, rocas activas y distancia adecuada al Sol.', subs:[['💧','Agua líquida','El agua líquida ayuda a que la vida conocida pueda funcionar.'],['🧲','Escudo invisible','El campo magnético ayuda a protegernos de partículas solares.']]}],
    [/marte/i, {s:'Marte es rojo por polvo con óxidos de hierro: algo parecido al herrumbre.', subs:[['🧊','Hielo escondido','Marte tiene hielo en polos y bajo algunas zonas del suelo.'],['🏞️','Ríos antiguos','Rocas y canales sugieren que alguna vez corrió agua líquida.']]}],
    [/júpiter/i, {s:'Júpiter es tan grande que más de 1.300 Tierras cabrían dentro de él.', subs:[['🌀','Tormenta gigante','La Gran Mancha Roja es una tormenta enorme observada desde hace siglos.'],['🛡️','Gravedad poderosa','Su gravedad puede atraer o desviar objetos pequeños del sistema solar.']]}],
    [/saturno/i, {s:'Los anillos de Saturno no son sólidos: son millones de pedazos de hielo y roca orbitando.', subs:[['🧊','Anillos de hielo','Muchos fragmentos son tan pequeños como polvo y otros como rocas grandes.'],['🌙','Titán','Una de sus lunas, Titán, tiene atmósfera densa y lagos de metano.']]}],
    [/luna/i, {s:'La Luna no brilla sola: refleja luz del Sol, como si fuera un espejo de roca.', subs:[['🌊','Mareas','Su gravedad ayuda a mover las mareas del océano.'],['📏','Se aleja','La Luna se aleja de la Tierra unos centímetros por año.']]}],
    [/año luz/i, {s:'Un año luz no mide tiempo: mide una distancia enorme, la que recorre la luz en un año.', subs:[['💡','Luz rapidísima','La luz viaja cerca de 300.000 km por segundo.'],['👀','Mirar pasado','Ver estrellas lejanas es ver luz que salió hace mucho tiempo.']]}],
    [/agujeros negros/i, {s:'Un agujero negro no es un agujero común: es una región donde la gravedad es tan fuerte que ni la luz escapa.', subs:[['🕳️','Límite sin regreso','El borde se llama horizonte de eventos.'],['🌌','No aspira todo','No “chupa” todo el universo; afecta sobre todo lo que está muy cerca.']]}],

    [/mamíferos/i, {s:'Mamífero viene con una clave: las crías toman leche. Por eso una ballena, un murciélago, un perro y tú comparten club.', subs:[['🍼','Leche materna','Las crías de mamíferos se alimentan con leche al comienzo de la vida.'],['🦇','Club variado','Hay mamíferos que vuelan, nadan, corren o viven bajo tierra.']]}],
    [/aves/i, {s:'Las plumas no son solo para volar: también abrigan, camuflan y sirven para comunicar.', subs:[['🪶','Plumas multitarea','Pueden ayudar al vuelo, al calor, al color y a la protección.'],['🥚','Huevos','Las aves ponen huevos con cáscara que protege al embrión.']]}],
    [/insectos/i, {s:'Si tiene seis patas y cuerpo en tres partes, probablemente estás mirando un insecto.', subs:[['🦗','Tres partes','Su cuerpo se divide en cabeza, tórax y abdomen.'],['🌍','Muchísimos','Los insectos son uno de los grupos animales más diversos del planeta.']]}],
    [/abejas/i, {s:'Sin polinizadores, muchas frutas y semillas serían más difíciles de producir.', subs:[['🌸','Polen viajero','Al visitar flores, las abejas trasladan polen.'],['🍯','Colmena','En la colmena hay tareas: cuidar, buscar alimento, limpiar y defender.']]}],
    [/hormigas/i, {s:'Una colonia de hormigas puede funcionar como una ciudad diminuta con caminos, trabajos y señales.', subs:[['👃','Mensajes químicos','Usan sustancias llamadas feromonas para dejar rastros.'],['🏗️','Trabajo repartido','No todas hacen lo mismo: algunas buscan comida y otras cuidan o defienden.']]}],
    [/pulpos/i, {s:'Los pulpos pueden resolver problemas, abrir recipientes y cambiar de color para esconderse.', subs:[['🐙','Brazos atentos','Sus brazos tienen muchas neuronas y exploran con precisión.'],['🎨','Camuflaje','Cambian color y textura de piel muy rápido.']]}],
    [/delfines/i, {s:'Los delfines usan sonidos como un sonar: envían clics y escuchan el eco.', subs:[['📡','Eco bajo el agua','El eco les ayuda a ubicar peces y objetos.'],['🌬️','Respiran aire','Aunque viven en el mar, suben a respirar.']]}],
    [/murciélagos/i, {s:'Los murciélagos no son aves: son mamíferos y muchos “ven” con ecos en la oscuridad.', subs:[['🦇','Vuelo real','Son los únicos mamíferos con vuelo sostenido.'],['🌙','Noche activa','Muchos cazan insectos durante la noche.']]}],

    [/paleolítico/i, {s:'El Paleolítico duró muchísimo: no fue una época de “cavernas simples”, sino de herramientas, fuego, arte y aprendizaje.', subs:[['🪨','Herramientas','La piedra tallada ayudó a cortar, raspar y cazar.'],['🔥','Fuego','Controlar el fuego cambió comida, protección y vida en grupo.']]}],
    [/agricultura/i, {s:'La agricultura hizo que muchos grupos dejaran de moverse tanto y empezaran a formar aldeas más estables.', subs:[['🌾','Sembrar futuro','Cultivar permite guardar alimento para después.'],['🏘️','Aldeas','Con más alimento, algunas comunidades crecieron y se organizaron distinto.']]}],
    [/escritura nació/i, {s:'La escritura no nació solo para poemas: también sirvió para contar granos, impuestos, compras y acuerdos.', subs:[['📋','Memoria externa','Escribir ayuda a no depender solo de la memoria.'],['🏺','Tablillas','En Mesopotamia se escribía sobre arcilla con signos cuneiformes.']]}],
    [/mesopotamia/i, {s:'Mesopotamia significa “entre ríos”: allí el Tigris y el Éufrates ayudaron a crecer ciudades tempranas.', subs:[['🏙️','Ciudades','Aparecieron templos, comercio, oficios y administración.'],['✍️','Cuneiforme','Usaron una escritura hecha con marcas en forma de cuña.']]}],
    [/egipto/i, {s:'El Nilo era como una gran carretera de agua: ayudaba a sembrar, viajar y organizar el antiguo Egipto.', subs:[['🌊','Crecidas','Las crecidas dejaban tierras fértiles para cultivar.'],['🛶','Transporte','El río facilitaba mover personas, alimentos y materiales.']]}],
    [/roma/i, {s:'Los caminos romanos conectaron territorios enormes; algunos trazos aún inspiran rutas actuales.', subs:[['🛣️','Caminos','Servían para comercio, ejército y mensajes.'],['🏛️','Ciudad y ley','Roma dejó huellas en arquitectura, derecho y lenguas.']]}],
    [/mayas/i, {s:'Los mayas usaron calendarios precisos y también una forma del cero antes de que Europa lo usara ampliamente.', subs:[['📅','Calendarios','Medían ciclos del tiempo con gran detalle.'],['🔢','Cero','El cero ayudó a escribir números y fechas.']]}],
    [/imprenta/i, {s:'La imprenta hizo que un mismo texto pudiera viajar mucho más rápido y barato que copiándolo a mano.', subs:[['📚','Más libros','Aumentó la circulación de textos.'],['🗣️','Ideas viajeras','Ayudó a difundir debates, ciencias y noticias.']]}],

    [/fotosíntesis/i, {s:'Una planta no “come” tierra: fabrica azúcares usando luz, agua y dióxido de carbono.', subs:[['☀️','Luz útil','La energía de la luz ayuda a producir alimento.'],['🌬️','Oxígeno','En el proceso se libera oxígeno.']]}],
    [/raíces/i, {s:'Las raíces no solo sujetan: buscan agua, minerales y a veces se comunican con hongos del suelo.', subs:[['💧','Agua','Absorben agua y minerales.'],['🍄','Alianzas','Muchas raíces se asocian con hongos llamados micorrizas.']]}],
    [/semillas/i, {s:'Una semilla es una planta en pausa: guarda una vida posible dentro de una pequeña cápsula.', subs:[['🛡️','Protección','La cubierta protege al embrión.'],['🌱','Despertar','Con agua, temperatura y oxígeno puede germinar.']]}],
    [/carnívoras/i, {s:'Algunas plantas comen insectos porque viven en suelos pobres en ciertos nutrientes.', subs:[['🪰','Trampa','Atrapan animales pequeños con hojas modificadas.'],['🧪','Nutrientes','Obtienen sustancias que el suelo no les ofrece fácilmente.']]}],

    [/cero/i, {s:'El cero parece nada, pero cambió todo: permite escribir 10, 100 y 1000 sin inventar símbolos nuevos.', subs:[['0️⃣','Nada con lugar','En un número, el cero puede marcar una posición.'],['🧮','Cálculos grandes','Ayuda a hacer cuentas enormes de forma más ordenada.']]}],
    [/primos/i, {s:'Los números primos son como números con pocas puertas: solo se dividen exacto por 1 y por sí mismos.', subs:[['🔐','Clave digital','Algunas formas de seguridad digital usan primos grandes.'],['🧱','Ladrillos','Muchos números pueden descomponerse en primos.']]}],
    [/infinito/i, {s:'El infinito no es “un número gigante”: es una idea para pensar algo que no termina.', subs:[['∞','Sin final','Sirve para imaginar procesos que continúan.'],['🧠','Idea poderosa','Obliga a pensar con reglas especiales.']]}],
    [/probabilidad/i, {s:'La probabilidad no adivina el futuro: ayuda a medir qué tan posible es algo.', subs:[['🎲','Juegos','Aparece en dados, cartas y decisiones.'],['📊','Riesgo','Ayuda a comparar posibilidades.']]}]
  ];

  const worldHooks={
    cosmos:['En el espacio, casi todo se entiende preguntando distancia, luz y movimiento.','El cielo parece quieto, pero está lleno de viajes, giros y señales antiguas.','Un dato espacial casi siempre esconde una escala enorme.'],
    animals:['En la vida animal, una forma rara casi siempre tiene una función.','Los animales tienen trucos: camuflaje, sonidos, rutas, venenos, cooperación o memoria.','Un bicho pequeño puede ser clave para un ecosistema entero.'],
    dinos:['Un fósil es una pista, no solo un hueso viejo.','La roca puede guardar una noticia de hace millones de años.','Los dinosaurios ayudan a imaginar un planeta muy distinto al actual.'],
    ocean:['El océano tiene pisos: luz arriba, presión y oscuridad abajo.','El mar no es solo agua: mueve calor, vida, alimento y clima.','Bajo el agua hay señales, corrientes y criaturas que parecen de otro planeta.'],
    hist:['La historia también vive en comidas, caminos, objetos, fiestas y palabras.','Un cambio antiguo puede seguir afectando cómo vivimos hoy.','A veces un objeto cotidiano cuenta más que una corona.'],
    cells:['Lo invisible también trabaja: células, señales, energía e instrucciones.','Tu cuerpo funciona con millones de procesos pequeños coordinados.','Una célula parece pequeña, pero puede hacer trabajos sorprendentes.'],
    earth:['La Tierra no está quieta: se mueve, se rompe, se enfría, se calienta y se transforma.','Un paisaje puede parecer tranquilo, pero está cambiando poco a poco.','Rocas, agua, aire y vida forman un sistema conectado.'],
    inv:['Un invento nace de un problema, no de la nada.','Muchos inventos fallaron antes de funcionar bien.','Una herramienta cambia lo que una persona o una comunidad puede hacer.'],
    brain:['El cerebro aprende mejor cuando algo sorprende, emociona o se practica.','Pensar, sentir, moverse y recordar trabajan juntos.','El cerebro no es una caja fija: cambia con lo que haces.'],
    plants:['Las plantas parecen quietas, pero trabajan todo el día.','Una hoja, una raíz o una semilla pueden esconder una estrategia.','Sin plantas, gran parte de la vida cotidiana sería imposible.'],
    art:['El arte puede cambiar lo que miras, sientes o recuerdas.','Una imagen, un ritmo o un color pueden contar sin explicar.','Crear es mezclar memoria, emoción, técnica e imaginación.'],
    chem:['La química aparece cuando cocinas, limpias, respiras o ves oxidarse un metal.','La materia cambia de forma, estado, mezcla o enlaces.','Una reacción es como reorganizar piezas invisibles.'],
    cultures:['Una cultura es una forma de recordar, celebrar, saludar, comer y explicar el mundo.','Las palabras, músicas y comidas viajan con las personas.','Un objeto cultural puede ser un mapa de historias.'],
    numbers:['Las matemáticas no son solo cuentas: son patrones, reglas y formas de pensar.','Un buen número puede esconder una historia, un juego o una decisión.','Medir, comparar y estimar ayudan a entender el mundo.']
  };

  function findExact(c){ return exact.find(([rx])=>rx.test(c.t)); }
  function genericSabel(c,idx){ const hooks=worldHooks[c.w]||worldHooks.cosmos; return hooks[idx%hooks.length]; }
  function genericSubs(c,idx){
    const simple=softer(c.fact);
    const hooks=worldHooks[c.w]||worldHooks.cosmos;
    return [
      {ico:'🧠',t:'En sencillo',fact:`${simple}`},
      {ico:'✨',t:'Dato para contar',fact:`${hooks[(idx+1)%hooks.length]}`}
    ];
  }
  CAPSULES.forEach((c,idx)=>{
    const match=findExact(c);
    c.factLabel='💡 ¿Sabías que...?';
    c.sabelotodoLabel='🤓 Modo sabelotodo';
    if(match){
      c.sabelotodo=match[1].s;
      c.subs=match[1].subs.map(x=>({ico:x[0],t:x[1],fact:x[2]}));
    }else{
      c.sabelotodo=genericSabel(c,idx);
      c.subs=genericSubs(c,idx);
    }
    if(c.bonus){
      c.fact=`Encontraste una cápsula bonus de ${(WORLDS.find(w=>w.id===c.w)?.discipline)||'este mundo'}. No es tarea: es un secreto extra para tu colección.`;
      c.sabelotodo='Las tarjetas bonus aparecen cuando ya avanzaste bastante: son como puertas escondidas del mapa.';
      c.subs=[{ico:'🎁',t:'Secreto extra',fact:'Esta cápsula no reemplaza el camino: lo agranda con una curiosidad adicional.'},{ico:'🗺️',t:'Mapa extendido',fact:'Cuando aparece, el mundo gana un nuevo punto de exploración.'}];
    }
  });
})();




/* Atlas del Asombro · Tienda de mundos v18
   Mundos desbloqueables con monedas. No usa personajes ni marcas protegidas: crea mundos originales inspirados en intereses infantiles. */
const SHOP_WORLD_IDS = ['emotions','social','ufo','anime_dojo'];
const SHOP_PRICES = { emotions:420, social:320, ufo:380, anime_dojo:420 };
const SHOP_META = {
  emotions:{tag:'premium emocional',why:'Cerebro, cuerpo y emociones sin personajes copiados.'},
  social:{tag:'convivencia',why:'Escucha, límites, amistad y cooperación.'},
  ufo:{tag:'misterios con ciencia',why:'OVNIs/FANI, exoplanetas y pensamiento crítico.'},
  anime_dojo:{tag:'aventura visual',why:'Anime como lenguaje narrativo, sin usar personajes protegidos.'}
};
function isShopWorld(id){ return SHOP_WORLD_IDS.includes(id); }
function worldPrice(id){ return SHOP_PRICES[id] || 0; }
function worldUnlocked(id){ return !isShopWorld(id) || !!(window.U || U)?.shopWorlds?.includes(id); }
function ensureShopState(){ if(typeof U==='undefined' || !U) return; if(!Array.isArray(U.shopWorlds)) U.shopWorlds=[]; }
function buyShopWorld(id){
  ensureShopState();
  if(!isShopWorld(id)) return {ok:false,msg:'Este mundo ya pertenece al Atlas base.'};
  if(U.shopWorlds.includes(id)) return {ok:true,msg:'Este mundo ya está desbloqueado.'};
  const price=worldPrice(id);
  if((U.coins||0)<price) return {ok:false,msg:`Necesitas ${price-(U.coins||0)} monedas más para desbloquear este mundo.`};
  U.coins-=price; U.shopWorlds.push(id); if(!U.visitedWorlds.includes(id)) U.visitedWorlds.push(id); saveState();
  return {ok:true,msg:'¡Mundo desbloqueado!'};
}

