  const CERT_PATCH = [{"id": "emotion_explorer", "n": "Explorador de Emociones", "ico": "💗", "desc": "Cerebro, cuerpo y emociones sin personajes copiados.", "worlds": ["emotions"], "kind": "world"}, {"id": "social_bridge", "n": "Constructor de Vínculos", "ico": "🤝", "desc": "Escucha, límites, amistad y cooperación.", "worlds": ["social"], "kind": "world"}, {"id": "cosmic_file", "n": "Investigador del Archivo Cósmico", "ico": "🛸", "desc": "Misterios del cielo con pensamiento crítico.", "worlds": ["ufo"], "kind": "world"}, {"id": "dojo_manga_hero", "n": "Maestro de Mangas y Héroes", "ico": "🥋", "desc": "Manga, anime y cultura de aventura visual.", "worlds": ["anime_dojo"], "kind": "world"}, {"id": "olympus_hero", "n": "Viajero del Olimpo", "ico": "🏺", "desc": "Dioses, héroes, viajes y preguntas humanas.", "worlds": ["olympus_epic"], "kind": "world"}, {"id": "literary_cartographer", "n": "Cartógrafo de Libros Mágicos", "ico": "📚", "desc": "Libros, autores y relatos que cambiaron la imaginación.", "worlds": ["literature"], "kind": "world"}];

  function applyWorldPatch(){
    for(const wid of WORLD_ORDER){
      const patch=WORLD_PATCH[wid];
      if(!patch) continue;
      if(!patch.bg) patch.bg = `linear-gradient(145deg, rgba(255,255,255,.10), rgba(255,255,255,.03)), radial-gradient(circle at 20% 5%, ${patch.col}55, transparent 38%), #091027`;
      if(!patch.mapBg) patch.mapBg = `radial-gradient(circle at 50% 10%, ${patch.col}22, transparent 32%), radial-gradient(circle at 80% 55%, ${patch.col}18, transparent 28%), #07091a`;
      const pos=WORLDS.findIndex(w=>w.id===wid);
      if(pos>=0) WORLDS[pos]=Object.assign({}, WORLDS[pos], patch);
      else WORLDS.push(Object.assign({id:wid}, patch));
    }
    WORLDS.sort((a,b)=>{ const ia=WORLD_ORDER.indexOf(a.id), ib=WORLD_ORDER.indexOf(b.id); return (ia<0?999:ia)-(ib<0?999:ib); });
  }
  function applyShopPatch(){
    try{
      if(typeof SHOP_WORLD_IDS!=='undefined') SHOP_IDS.forEach(id=>{ if(!SHOP_WORLD_IDS.includes(id)) SHOP_WORLD_IDS.push(id); });
      if(typeof SHOP_PRICES!=='undefined') Object.assign(SHOP_PRICES, SHOP_PRICES_PATCH);
      if(typeof SHOP_META!=='undefined') Object.assign(SHOP_META, SHOP_META_PATCH);
    }catch(e){}
  }
  function replaceCapsules(){
    const ids=new Set(WORLD_ORDER);
    for(let i=CAPSULES.length-1;i>=0;i--){ if(ids.has(CAPSULES[i].w)) CAPSULES.splice(i,1); }
    for(const wid of WORLD_ORDER){
      for(const card of DATA[wid]||[]){ CAPSULES.push(card); }
    }
  }
  function applyCertificates(){
    try{
      if(typeof CERTIFICATES==='undefined') return;
      for(const c of CERT_PATCH){
        const pos=CERTIFICATES.findIndex(x=>x.id===c.id);
        if(pos>=0) CERTIFICATES[pos]=Object.assign({}, CERTIFICATES[pos], c);
        else CERTIFICATES.push(c);
      }
    }catch(e){}
  }
  applyWorldPatch();
  applyShopPatch();
  replaceCapsules();
  applyCertificates();
  window.ATLAS_EDITORIAL_DOCX_V27={version:'v27',source:'estructura_ordenada_capsulas_mundos.docx',worlds:WORLD_ORDER.length,cards:CAPSULES.filter(c=>WORLD_ORDER.includes(c.w)).length,base:CAPSULES.filter(c=>WORLD_ORDER.includes(c.w)&&!c.bonus).length,bonus:CAPSULES.filter(c=>WORLD_ORDER.includes(c.w)&&c.bonus).length};
