const STORAGE_KEY = 'atlas_asombro_dsebi_v27';
const LEGACY_STORAGE_KEYS = ['atlas_asombro_dsebi_v26','atlas_asombro_dsebi_v25','atlas_asombro_dsebi_v24','atlas_asombro_dsebi_v21','atlas_asombro_dsebi_v20','atlas_asombro_dsebi_v19','atlas_asombro_dsebi_v18','atlas_asombro_dsebi_v17','atlas_asombro_dsebi_v16','atlas_asombro_dsebi_v15','atlas_asombro_dsebi_v14','atlas_asombro_dsebi_v13','atlas_asombro_dsebi_v12','atlas_asombro_dsebi_v11'];
let U = null;
let currentWorld = null;
let currentCard = null;
let quizState = null;

function freshState(){
  const res={}; WORLDS.forEach(w=>res[w.id]=0);
  return {name:'', avatar:'🧭', xp:0, coins:0, seen:[], favs:[], badges:[], visitedWorlds:[], quiz:{}, trophies:[], giftClaimed:{}, bonusUnlocked:{}, shopWorlds:[], lastWorld:null, res};
}
function loadState(){
  try{
    let raw=localStorage.getItem(STORAGE_KEY);
    if(!raw){
      for(const key of LEGACY_STORAGE_KEYS){
        raw=localStorage.getItem(key);
        if(raw) break;
      }
    }
    U=raw?{...freshState(),...JSON.parse(raw)}:freshState();
    if(raw && !localStorage.getItem(STORAGE_KEY)) localStorage.setItem(STORAGE_KEY, JSON.stringify(U));
  }
  catch(e){ U=freshState(); }
  WORLDS.forEach(w=>{ if(!U.res) U.res={}; if(U.res[w.id]===undefined)U.res[w.id]=0; });
  if(!Array.isArray(U.shopWorlds)) U.shopWorlds=[];
  try{ checkBadges(); saveState(); }catch(e){}
}
function saveState(){ localStorage.setItem(STORAGE_KEY, JSON.stringify(U)); }
function resetState(){ localStorage.removeItem(STORAGE_KEY); U=freshState(); location.reload(); }
function getRank(xp=U.xp){ let r=RANKS[0]; for(const rk of RANKS){ if(xp>=rk.xp) r=rk; } return r; }
function getRankProg(xp=U.xp){
  let cur=RANKS[0], nxt=RANKS[1] || null;
  for(let i=0;i<RANKS.length;i++){ if(xp>=RANKS[i].xp){ cur=RANKS[i]; nxt=RANKS[i+1]||null; } }
  if(!nxt) return {cur,nxt:null,prog:100,left:0};
  const prog=Math.max(0,Math.min(100,Math.round((xp-cur.xp)/(nxt.xp-cur.xp)*100)));
  return {cur,nxt,prog,left:nxt.xp-xp};
}
function worldById(id){ return WORLDS.find(w=>w.id===id); }
function allCaps(wid){ return CAPSULES.filter(c=>c.w===wid); }
function baseCaps(wid){ return CAPSULES.filter(c=>c.w===wid && !c.bonus); }
function bonusCap(wid){ return CAPSULES.find(c=>c.w===wid && c.bonus); }
function visibleCaps(wid){ return allCaps(wid).filter(c=>!c.bonus || U.bonusUnlocked[wid]); }
function seenCount(wid, includeBonus=false){ const list=includeBonus?visibleCaps(wid):baseCaps(wid); return list.filter(c=>U.seen.includes(c.id)).length; }
function worldProgress(wid){ const total=baseCaps(wid).length; return total?Math.round(seenCount(wid,false)/total*100):0; }
function visibleWorldProgress(wid){ const list=visibleCaps(wid); return list.length?Math.round(list.filter(c=>U.seen.includes(c.id)).length/list.length*100):0; }
function worldBaseComplete(wid){ const list=baseCaps(wid); return list.length>0 && list.every(c=>U.seen.includes(c.id)); }
function visibleWorldComplete(wid){ const list=visibleCaps(wid); return list.length>0 && list.every(c=>U.seen.includes(c.id)); }
function pendingGiftWorlds(){ return WORLDS.filter(w=>worldProgress(w.id)>=80 && !U.giftClaimed[w.id]); }
function claimGift(wid){
  if(worldProgress(wid)<80 || U.giftClaimed[wid]) return null;
  U.giftClaimed[wid]=true; U.bonusUnlocked[wid]=true; U.coins+=20; U.xp+=40; saveState();
  return bonusCap(wid);
}
function markSeen(cid){
  const c=CAPSULES.find(x=>x.id===cid); if(!c || U.seen.includes(cid)) return {fresh:false, card:c};
  U.seen.push(cid); U.xp += RXP[c.r] || 10; U.coins += Math.ceil((RXP[c.r]||10)/5); U.res[c.w]=(U.res[c.w]||0)+1; U.lastWorld=c.w;
  if(!U.visitedWorlds.includes(c.w)) U.visitedWorlds.push(c.w);
  const newBadges = checkBadges();
  saveState();
  return {fresh:true, card:c, newBadges};
}
function toggleFav(cid){
  if(U.favs.includes(cid)) U.favs = U.favs.filter(x=>x!==cid); else U.favs.push(cid);
  saveState(); return U.favs.includes(cid);
}
function checkBadges(){
  const defs = badgeDefinitions(); const unlocked=[];
  for(const b of defs){ if(!U.badges.includes(b.id) && b.cond()){ U.badges.push(b.id); unlocked.push(b); } }
  return unlocked;
}
function badgeDefinitions(){
  return [
    {id:'first',n:'Primer descubrimiento',ico:'🌟',desc:'Exploraste tu primera cápsula.',cond:()=>U.seen.length>=1},
    {id:'ten',n:'Diez asombros',ico:'🔭',desc:'10 cápsulas exploradas.',cond:()=>U.seen.length>=10},
    {id:'fifty',n:'Constelación curiosa',ico:'✨',desc:'50 cápsulas exploradas.',cond:()=>U.seen.length>=50},
    {id:'hundred',n:'Cazador de saberes',ico:'💎',desc:'100 cápsulas exploradas.',cond:()=>U.seen.length>=100},
    {id:'fav5',n:'Coleccionista amable',ico:'💛',desc:'5 cápsulas guardadas como favoritas.',cond:()=>U.favs.length>=5},
    {id:'gift1',n:'Primer regalo abierto',ico:'🎁',desc:'Reclamaste una tarjeta regalo.',cond:()=>Object.values(U.giftClaimed).some(Boolean)},
    {id:'quiz1',n:'Primer quiz completado',ico:'🧩',desc:'Terminaste un quiz de mundo.',cond:()=>Object.keys(U.quiz).length>=1},
    {id:'cert1',n:'Primer certificado',ico:'📜',desc:'Obtuviste un certificado.',cond:()=>certificateStats().earned.length>=1},
    {id:'world3',n:'Tres mundos avanzados',ico:'🌍',desc:'Alcanzaste 80% en tres mundos.',cond:()=>WORLDS.filter(w=>worldProgress(w.id)>=80).length>=3},
    {id:'atlas_all',n:'Atlas gigantesco',ico:'🏆',desc:'Completaste todos los mundos base.',cond:()=>WORLDS.filter(w=>typeof worldUnlocked!=='function'||worldUnlocked(w.id)).every(w=>worldBaseComplete(w.id))}
  ];
}
function certificateScore(cert){
  if(cert.kind==='global'){
    const avg = WORLDS.reduce((a,w)=>a+worldProgress(w.id),0)/WORLDS.length;
    const quizBoost = Math.min(10,Object.keys(U.quiz).length*2);
    const badgeBoost = Math.min(10,U.badges.length);
    return Math.min(100,Math.round(avg+quizBoost+badgeBoost));
  }
  const avg=cert.worlds.reduce((a,wid)=>a+worldProgress(wid),0)/cert.worlds.length;
  const quizAvg=cert.worlds.reduce((a,wid)=>a+(U.quiz[wid]?.pct||0),0)/cert.worlds.length;
  const badgeBoost=Math.min(8,U.badges.length);
  let score=Math.round(avg*.72 + quizAvg*.18 + badgeBoost);
  if(cert.kind==='world' && cert.worlds.every(w=>worldBaseComplete(w))) score=Math.max(score,92);
  if(cert.kind==='quiz' && cert.worlds.every(w=>worldProgress(w)>=90) && quizAvg>=80) score=Math.max(score,92);
  return Math.min(100,score);
}
function certificateStats(){
  const items=CERTIFICATES.map(c=>({...c,score:certificateScore(c)}));
  return {items, earned:items.filter(c=>c.score>=80)};
}
function buildQuiz(wid){
  const done=visibleCaps(wid).filter(c=>U.seen.includes(c.id));
  if(done.length<4) return null;
  const pool=[...done].sort(()=>Math.random()-.5).slice(0,Math.min(8,done.length));
  const worldTitles=baseCaps(wid).map(c=>c.t);
  return pool.map(c=>{
    const distractors=worldTitles.filter(t=>t!==c.t).sort(()=>Math.random()-.5).slice(0,3);
    const opts=[c.t,...distractors].sort(()=>Math.random()-.5);
    return {card:c, q:`¿Qué cápsula explica esta idea? “${c.fact.slice(0,125)}${c.fact.length>125?'...':''}”`, opts, ok:opts.indexOf(c.t), why:(c.idea||c.sabelotodo||c.subs?.[0]?.fact||'Buen intento: vuelve a la tarjeta y revisa la pista principal.')};
  });
}
function registerQuiz(wid,score,total){ U.quiz[wid]={score,total,pct:Math.round(score/total*100),at:new Date().toISOString()}; checkBadges(); saveState(); }

