let resizeTimer=null;
const WORLD_DECOR={
  cosmos:['✦','✧','✨','⋆','☄️','🪐','🌙'],
  animals:['🐾','🪶','🍃','🐟','🦋','🐚','🌿'],
  dinos:['🦴','🌿','🦕','🦖','🥚','☄️','🪨'],
  ocean:['🐚','🌊','🐟','🪸','🫧','🐙','⭐'],
  hist:['🏺','📜','🗿','⚱️','🧭','🏛️','⏳'],
  cells:['🧬','🔬','🫧','⚛️','🧫','🧪','•'],
  earth:['⛰️','🪨','🌧️','🌋','🍃','☁️','🌍'],
  inv:['⚙️','🔧','💡','🛰️','🛠️','🔋','📡'],
  brain:['🧠','⚡','💭','🔍','🧩','💡','•'],
  plants:['🌿','🍃','🌱','🌼','🌳','🪴','☀️'],
  art:['🎨','🖌️','🎵','✨','🖼️','🎭','🌈'],
  chem:['⚗️','🧪','⚛️','🫧','💥','🔬','•'],
  cultures:['🌍','🧭','🏮','🎎','🎉','🍲','🗣️'],
  numbers:['🔢','➕','∞','△','○','⭐','½'],
  ufo:['🛸','✦','👽','📡','☄️','🛰️','?'],
  olympus_epic:['🏺','⚡','🦉','🌊','🏛️','📜','✨'],
  literature:['📚','✒️','📜','🌙','🕯️','✨','🦋']
};
function openWorld(wid){
  if(typeof worldUnlocked==='function' && !worldUnlocked(wid)){ renderShop(wid); return; }
  currentWorld=wid; U.lastWorld=wid; if(!U.visitedWorlds.includes(wid)) U.visitedWorlds.push(wid); saveState();
  renderMap(); showScreen('mapScreen'); playSound('module'); updateTop();
}
function renderMap(){
  if(!currentWorld) return;
  const w=worldById(currentWorld), caps=visibleCaps(currentWorld);
  const scroll=document.getElementById('mapScroll'), canvas=document.getElementById('mapCanvas'), svg=document.getElementById('mapSvg');
  document.getElementById('mapIcon').textContent=w.ico; document.getElementById('mapIcon').style.background=w.col+'22';
  document.getElementById('mapWorldName').textContent=w.n;
  document.getElementById('mapWorldProgress').textContent=`${seenCount(w.id,true)}/${caps.length} tarjetas visibles · ${worldProgress(w.id)}% base`;
  canvas.style.background=w.mapBg;

  let W=Math.max(320, Math.round(scroll.clientWidth || window.innerWidth || 360));
  if(window.innerWidth >= 1000) W=Math.min(980, W-22);
  canvas.style.width=W+'px';
  canvas.style.maxWidth=W+'px';
  canvas.style.margin='0 auto';

  const H=Math.max(980, caps.length*(W<430?150:140) + 240);
  canvas.style.height=H+'px';
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);
  canvas.querySelectorAll('.map-node').forEach(n=>n.remove());

  const cols = W<430 ? [0.24,0.74,0.36,0.66,0.50] : W<760 ? [0.18,0.72,0.34,0.66,0.50] : [0.16,0.50,0.82,0.34,0.66,0.24,0.76];
  const top=126, bottom=170, usable=H-top-bottom;
  const positions=caps.map((c,i)=>({x:cols[i%cols.length]*W,y:top+(i/(Math.max(1,caps.length-1)))*usable,card:c,index:i}));
  const trophy={x:.5*W,y:H-92,card:null,trophy:true};
  const pathPts=positions.concat([trophy]);
  let d=`M ${pathPts[0].x.toFixed(1)} ${pathPts[0].y.toFixed(1)}`;
  for(let i=1;i<pathPts.length;i++){
    const a=pathPts[i-1], b=pathPts[i];
    const c1y=a.y+(b.y-a.y)*.36, c2y=a.y+(b.y-a.y)*.64;
    d+=` C ${a.x.toFixed(1)},${c1y.toFixed(1)} ${b.x.toFixed(1)},${c2y.toFixed(1)} ${b.x.toFixed(1)},${b.y.toFixed(1)}`;
  }
  let deco='';
  const decoList=WORLD_DECOR[w.id]||[w.ico,'✨','✦','✧','○','•','⋆'];
  for(let i=0;i<42;i++){
    const x=Math.random()*W, y=Math.random()*H, fs=8+Math.random()*22, op=.04+Math.random()*.12;
    deco+=`<text x="${x.toFixed(0)}" y="${y.toFixed(0)}" font-size="${fs.toFixed(0)}" opacity="${op.toFixed(2)}" text-anchor="middle">${decoList[i%decoList.length]}</text>`;
  }
  svg.innerHTML=`<defs><filter id="glow"><feGaussianBlur stdDeviation="5" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>${deco}<path d="${d}" fill="none" stroke="${w.col}42" stroke-width="11" stroke-linecap="round" stroke-dasharray="18 13" filter="url(#glow)"/><path d="${d}" fill="none" stroke="${w.col}" stroke-width="2.4" stroke-linecap="round" opacity=".7"/>`;

  positions.forEach((p,i)=>{
    const c=p.card, done=U.seen.includes(c.id), prev=i===0 || U.seen.includes(caps[i-1].id), unlocked=prev || done;
    const side=p.x < W/2 ? 'right' : 'left';
    const node=document.createElement('button');
    node.className=`map-node map-node-card side-${side} ${done?'is-done':unlocked?'is-open':'is-locked'}`;
    node.style.left=p.x+'px'; node.style.top=p.y+'px';
    node.setAttribute('data-tip',unlocked?`${c.t}: toca para abrir la tarjeta`:'Explora la cápsula anterior para desbloquear esta.');
    node.setAttribute('data-card-id',c.id);
    node.innerHTML=`<span class="node-bubble ${done?'done':unlocked?'unlocked':'locked'}" style="border-color:${done?'#4ade80':unlocked?w.col:'rgba(255,255,255,.22)'}">${done?'✅':c.ico}</span><span class="node-mini-card" style="--nodeCol:${w.col}"><span class="mini-card-icon">${c.bonus?'🎁':c.ico}</span><span class="mini-card-text"><b>${c.mapTitle||c.t}</b><small>${c.mapKicker||'explorar'}</small></span></span>`;
    if(unlocked) node.onclick=()=>openCard(c.id); else node.onclick=()=>toast('Primero explora la tarjeta anterior.');
    canvas.appendChild(node);
  });

  if(worldProgress(w.id)>=80 && !U.giftClaimed[w.id]){
    const gy=trophy.y-6, gx=Math.max(74, Math.min(W-74, trophy.x-(W<430?78:108)));
    const g=document.createElement('button');
    g.className='map-node map-gift-node';
    g.style.left=gx+'px'; g.style.top=gy+'px';
    g.setAttribute('data-tip','Regalo desbloqueado: abre la cápsula bonus de este mundo');
    g.innerHTML=`<span class="node-bubble unlocked gift-bubble" aria-hidden="true">${giftSvg()}</span><span class="gift-map-label"><b>Regalo</b><small>abrir bonus</small></span>`;
    g.onclick=()=>openGift(w.id);
    canvas.appendChild(g);
  }

  const t=document.createElement('button');
  t.className='map-node trophy-node'; t.style.left=trophy.x+'px'; t.style.top=trophy.y+'px'; t.setAttribute('data-tip','Copa final del mundo');
  const ready=visibleWorldComplete(w.id);
  t.innerHTML=`<span class="node-bubble trophy-bubble ${ready?'unlocked':'locked'}" aria-hidden="true">${trophySvg()}</span><span class="node-mini-card trophy-card trophy-label"><span class="mini-card-icon">🏆</span><span class="mini-card-text"><b>Copa final</b><small>${ready?'reclamar premio':'termina el mapa'}</small></span></span>`;
  t.onclick=()=> ready ? claimWorldTrophy(w.id) : toast('La copa se activa al terminar todas las tarjetas visibles del mundo.');
  canvas.appendChild(t);

  const nextIdx=positions.findIndex(p=>!U.seen.includes(p.card.id));
  let target;
  const focusId=window.__focusCardId;
  const focusPos=focusId?positions.find(p=>p.card.id===focusId):null;
  if(window.__focusTrophy){ target=Math.max(0,trophy.y-260); window.__focusTrophy=false; }
  else if(focusPos){ target=Math.max(0,focusPos.y-220); window.__focusCardId=null; }
  else if(visibleWorldComplete(w.id)) target=Math.max(0,trophy.y-260);
  else if(nextIdx>=0) target=Math.max(0,positions[nextIdx].y-220);
  else target=Math.max(0,H-560);
  setTimeout(()=>{ scroll.scrollTo({top:target,behavior:'smooth'}); if(focusPos) focusCardOnMap(focusPos.card.id); },80);
}
window.addEventListener('resize',()=>{ clearTimeout(resizeTimer); resizeTimer=setTimeout(()=>{ if(document.getElementById('mapScreen').classList.contains('on')) renderMap(); },160); });
function focusCardOnMap(cid){
  const scroll=document.getElementById('mapScroll');
  const node=document.querySelector(`[data-card-id="${cid}"]`);
  if(!scroll||!node) return;
  const y=parseFloat(node.style.top||'0');
  scroll.scrollTo({top:Math.max(0,y-220),behavior:'smooth'});
  node.classList.add('focus-node');
  setTimeout(()=>node.classList.remove('focus-node'),1400);
}




/* Atlas del Asombro · UI v11
   Correcciones: tarjeta compacta, favoritos con secuencia propia, logros/medallas separados,
   copa estilizada y navegación robusta. */
const Sound={
  ctx:null, enabled:false,
  init(){try{this.ctx=this.ctx||new (window.AudioContext||window.webkitAudioContext)();this.enabled=true;}catch(e){}},
  tone(freq=440,dur=.08,type='sine',gain=.04,delay=0){
    if(!this.enabled||!this.ctx)return; const t=this.ctx.currentTime+delay;
    const o=this.ctx.createOscillator(), g=this.ctx.createGain(); o.type=type; o.frequency.setValueAtTime(freq,t);
    g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(gain,t+.012); g.gain.exponentialRampToValueAtTime(.0001,t+dur);
    o.connect(g); g.connect(this.ctx.destination); o.start(t); o.stop(t+dur+.04);
  },
  intro(){this.init(); const notes=[261.63,329.63,392,523.25,659.25,523.25,392,329.63,392,523.25,783.99,659.25,523.25,392,329.63,261.63]; notes.forEach((n,i)=>this.tone(n,.28,'triangle',.038,i*.32)); this.tone(130.8,1.8,'sine',.02,.05);},
  click(){this.tone(640,.045,'triangle',.025)},
  module(){[392,523,659].forEach((n,i)=>this.tone(n,.08,'triangle',.035,i*.07))},
  card(){[520,780].forEach((n,i)=>this.tone(n,.08,'sine',.03,i*.06))},
  complete(){[523,659,784,1046].forEach((n,i)=>this.tone(n,.18,'triangle',.04,i*.12))},
  gift(){[392,523,659,784,988].forEach((n,i)=>this.tone(n,.15,'triangle',.045,i*.09))},
  trophy(){[392,523,659,784,1046,1318].forEach((n,i)=>this.tone(n,.18,'triangle',.048,i*.1))}
};
function playSound(kind){ if(!Sound.enabled && kind!=='start') return; if(kind==='start') Sound.intro(); else if(Sound[kind]) Sound[kind](); }

/* v52 · helper global de escape HTML para funciones heredadas */
function escHTML(v){
  return String(v ?? '').replace(/[&<>"']/g, ch => ({
    '&':'&amp;',
    '<':'&lt;',
    '>':'&gt;',
    '"':'&quot;',
    "'":'&#39;'
  }[ch]));
}
window.escHTML = escHTML;

function showScreen(id){ document.querySelectorAll('.screen').forEach(s=>s.classList.remove('on')); const el=document.getElementById(id); if(el) el.classList.add('on'); }
function toast(msg,dur=2600){ const el=document.getElementById('toast'); if(!el)return; el.textContent=msg; el.classList.add('on'); clearTimeout(el._t); el._t=setTimeout(()=>el.classList.remove('on'),dur); }


/* v44 · PWA fijada al dominio final de Cloudflare Pages */
const ATLAS_PUBLIC_URL = 'https://sabias-que.pages.dev/';
function isExpectedAtlasOrigin(){
  return location.origin === 'https://sabias-que.pages.dev' || location.hostname === 'localhost' || location.hostname === '127.0.0.1';
}

let deferredInstallPrompt=null;
function installAppIconSvg(){
  return `<svg class="install-app-svg" viewBox="0 0 64 64" aria-hidden="true" focusable="false">
    <rect x="14" y="10" width="36" height="44" rx="10" fill="none" stroke="currentColor" stroke-width="4.5"/>
    <path d="M32 18v18" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round"/>
    <path d="M24 30l8 8 8-8" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>
    <path d="M22 46h20" fill="none" stroke="currentColor" stroke-width="4.5" stroke-linecap="round"/>
  </svg>`;
}
function isStandaloneMode(){ return window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone===true; }
function updateInstallAppVisibility(){
  const btn=document.getElementById('installAppBtn'); if(!btn) return;
  const supported = !!deferredInstallPrompt || isStandaloneMode();
  btn.classList.toggle('hidden', !supported);
  btn.disabled = isStandaloneMode();
  btn.dataset.tip = isStandaloneMode() ? 'La app ya está instalada' : 'Instalar como aplicación desde sabias-que.pages.dev';
  const label=btn.querySelector('b'); if(label) label.textContent=isStandaloneMode() ? 'Instalada' : 'Instalar';
}
async function triggerAppInstall(){
  if(!isExpectedAtlasOrigin()){
    toast('En celular instala desde https://sabias-que.pages.dev/ para que el acceso abra correctamente.', 4200);
    return;
  }
  if(isStandaloneMode()){ toast('La app ya está instalada en este dispositivo'); return; }
  if(!deferredInstallPrompt){ toast('Abre https://sabias-que.pages.dev/ en Chrome o Safari y usa instalar/agregar a pantalla de inicio.', 4200); return; }
  try{
    deferredInstallPrompt.prompt();
    const choice = await deferredInstallPrompt.userChoice;
    if(choice && choice.outcome==='accepted') toast('🎉 Atlas del Asombro se instalará como aplicación');
    else toast('Instalación cancelada por ahora');
    deferredInstallPrompt=null;
    updateInstallAppVisibility();
  }catch(e){ toast('No se pudo iniciar la instalación'); }
}
function setupPWAInstall(){
  const slot=document.querySelector('#installAppBtn .install-ico-slot'); if(slot && !slot.innerHTML.trim()) slot.innerHTML=installAppIconSvg();
  const btn=document.getElementById('installAppBtn'); if(btn && !btn.dataset.ready){ btn.dataset.ready='1'; btn.addEventListener('click', triggerAppInstall); }
  window.addEventListener('beforeinstallprompt', e=>{ e.preventDefault(); deferredInstallPrompt=e; updateInstallAppVisibility(); });
  window.addEventListener('appinstalled', ()=>{ deferredInstallPrompt=null; updateInstallAppVisibility(); toast('✅ Atlas del Asombro instalado'); });
  updateInstallAppVisibility();
  /* service worker retirado en v47 */
}

function confetti(amount=70){ const fx=document.getElementById('fxLayer'); if(!fx)return; const colors=['#7c6ffd','#38bdf8','#4ade80','#f7c948','#f472b6','#fb923c']; for(let i=0;i<amount;i++){ const s=document.createElement('i'); s.className='confetti'; s.style.left=Math.random()*100+'vw'; s.style.background=colors[i%colors.length]; s.style.animationDelay=(Math.random()*.35)+'s'; s.style.transform=`rotate(${Math.random()*360}deg)`; fx.appendChild(s); setTimeout(()=>s.remove(),2200); } }
function makeParticles(id,count=76){ const box=document.getElementById(id); if(!box||box.dataset.ready)return; box.dataset.ready=1; const colors=['#7c6ffd','#38bdf8','#4ade80','#f7c948','#f472b6','#ffffff']; for(let i=0;i<count;i++){ const d=document.createElement('i'); d.className='dot'; const size=1+Math.random()*4; d.style.width=size+'px'; d.style.height=size+'px'; d.style.left=Math.random()*100+'%'; d.style.top=Math.random()*100+'%'; d.style.background=colors[i%colors.length]; d.style.setProperty('--x',(Math.random()*120-60)+'px'); d.style.setProperty('--y',(-40-Math.random()*120)+'px'); d.style.setProperty('--d',(8+Math.random()*12)+'s'); d.style.animationDelay=(-Math.random()*12)+'s'; box.appendChild(d); } }
function closeOverlay(id){ const el=document.getElementById(id); if(el)el.classList.add('hidden'); }
function openModal(html){ const m=document.getElementById('modalBox'); if(!m)return; m.innerHTML=html; document.getElementById('modalOverlay')?.classList.remove('hidden'); }

let cardContext={mode:'world', list:[], index:-1};
let worldDeckIndex=0;
const WORLD_VIEW_KEY='atlas_world_view_v35';
let worldViewMode=localStorage.getItem(WORLD_VIEW_KEY) || 'grid';
function setTxt(id,val){ const el=document.getElementById(id); if(el) el.textContent=val; }
function difficultTerms(text){
  let out=String(text||'');
  if(!out) return out;
  const defs=[
    ['sistema posicional','sistema posicional (el lugar cambia el valor: 2 no vale igual en 2 que en 20)'],
    ['neuroplasticidad','neuroplasticidad (capacidad del cerebro de cambiar con la práctica y la experiencia)'],
    ['micorrizas','micorrizas (alianzas entre hongos y raíces de plantas)'],
    ['tectónicas','placas tectónicas (enormes piezas de la corteza terrestre que se mueven muy lentamente)'],
    ['tectónica','tectónica (movimiento lento de grandes partes de la corteza terrestre)'],
    ['fusión nuclear','fusión nuclear (unión de partículas muy pequeñas que libera energía)'],
    ['dióxido de carbono','dióxido de carbono (un gas del aire que las plantas usan en la fotosíntesis)'],
    ['fotosíntesis','fotosíntesis (forma en que muchas plantas usan luz para fabricar alimento)'],
    ['atmósfera','atmósfera (capa de gases que rodea un planeta)'],
    ['salinidad','salinidad (cantidad de sal disuelta en el agua)'],
    ['probabilidad','probabilidad (qué tan posible es que algo ocurra)'],
    ['evolución','evolución (cambio de los seres vivos durante muchísimas generaciones)'],
    ['neuronas','neuronas (células que llevan mensajes en el cerebro y los nervios)'],
    ['neurona','neurona (célula que lleva mensajes en el cerebro y los nervios)'],
    ['moléculas','moléculas (grupos de átomos unidos)'],
    ['molécula','molécula (grupo de átomos unidos)'],
    ['átomos','átomos (piezas muy pequeñas de la materia)'],
    ['átomo','átomo (pieza muy pequeña de la materia)'],
    ['gravedad','gravedad (fuerza que atrae unas cosas hacia otras)'],
    ['ADN','ADN (instrucciones internas de los seres vivos)'],
    ['pH','pH (medida que indica qué tan ácida o básica es una sustancia)']
  ];
  const placeholders=[];
  defs.sort((a,b)=>b[0].length-a[0].length).forEach(([term,repl],i)=>{
    const safeTerm=term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    const re=new RegExp(`\\b${safeTerm}\\b(?!\\s*\\()`, term.toLowerCase()===term ? 'gi' : 'g');
    out=out.replace(re,match=>{
      const token=`@@TERM_${placeholders.length}@@`;
      const adjusted = match[0]===match[0]?.toUpperCase() ? repl.replace(term, match) : repl.replace(new RegExp(term,'i'), match);
      placeholders.push([token, adjusted]);
      return token;
    });
  });
  for(const [token,value] of placeholders) out=out.replaceAll(token,value);
  return out.replace(/\s+/g,' ').trim();
}
function worldBadgeCount(kind){ return badgeDefinitions().filter(b=>b.type===kind && U.badges.includes(b.id)).length; }
function updateTop(){
  try{ checkBadges(); saveState(); }catch(e){}
  const rp=getRankProg(); const r=rp.cur; const pending=pendingGiftWorlds(); const certs=certificateStats().earned.length;
  const readyQuiz=WORLDS.filter(w=>visibleCaps(w.id).filter(c=>U.seen.includes(c.id)).length>=4).length;
  const completedQuiz=Object.keys(U.quiz||{}).length;
  setTxt('homeAvatar',U.avatar); setTxt('helloName',`Hola, ${U.name||'Explorador'}`); setTxt('rankLabel',`${r.ico} ${r.n} · ${U.coins} monedas`); setTxt('xpText',U.xp+' XP');
  const fill=document.getElementById('xpFill'); if(fill) fill.style.width=rp.prog+'%';
  setTxt('homeTitle',U.seen.length?`Sigamos explorando, ${U.name}`:`${U.name}, elige tu primer mundo`);
  const gift=document.getElementById('giftBtn'); if(gift){ gift.classList.toggle('hidden',pending.length===0); gift.classList.toggle('pulse-gift',pending.length>0); gift.textContent='🎁'; }
  setTxt('badgeMini',U.badges.length);
  setTxt('certMini',certs);
  setTxt('rewardMini',pending.length);
  setTxt('favMini',U.favs.length);
  setTxt('quizMini',readyQuiz || completedQuiz || 0);
  setTxt('shopMini',U.coins||0);
  const qBtn=document.getElementById('homeQuizBtn'); if(qBtn) qBtn.dataset.tip = readyQuiz ? `${readyQuiz} quiz disponibles` : (completedQuiz?`${completedQuiz} quiz completados`:'Explora 4 tarjetas de un mundo para activar quiz');
}
function renderWorlds(){
  const grid=document.getElementById('worldGrid'); if(!grid)return;
  const worldsHtml=WORLDS.map(w=>{ const locked=typeof worldUnlocked==='function' && !worldUnlocked(w.id); const price=typeof worldPrice==='function'?worldPrice(w.id):0; const p=locked?0:worldProgress(w.id), v=locked?0:seenCount(w.id,true), total=visibleCaps(w.id).length, gift=!locked&&worldProgress(w.id)>=80&&!U.giftClaimed[w.id]; const complete=!locked&&worldBaseComplete(w.id), active=p>0&&!complete; const stateType=locked?'locked':gift?'gift':complete?'complete':active?'active':'new'; const statusHtml=worldStatusBadge(stateType,locked,price); return `<button class="world-card world-card-v5 ${locked?'locked-shop-world':''}" style="background:${w.bg};--worldCol:${w.col}" data-tip="${locked?'Desbloquear en tienda':w.discipline}" onclick="${locked?`renderShop('${w.id}')`:`openWorld('${w.id}')`}"><span class="big">${locked?'🔒':w.ico}</span>${statusHtml}<span class="world-res">${w.res||'✨'}</span><h4>${w.n}</h4><p>${locked?`Mundo desbloqueable · ${SHOP_META?.[w.id]?.tag||'premium'}`:w.discipline}</p><div class="bar"><i style="width:${p}%"></i></div><div class="world-meta"><span>${locked?'Tienda':v+'/'+total+' tarjetas'}</span><span>${locked?price+' 🪙':p+'%'}</span></div></button>`; }).join('');
  grid.innerHTML=worldsHtml;
  renderWorldDeck();
  setWorldView(worldViewMode,false);
}
function renderWorldDeck(){
  const deck=document.getElementById('worldDeck'); if(!deck) return;
  if(worldDeckIndex<0) worldDeckIndex=0; if(worldDeckIndex>=WORLDS.length) worldDeckIndex=WORLDS.length-1;
  const w=WORLDS[worldDeckIndex]; const locked=typeof worldUnlocked==='function' && !worldUnlocked(w.id); const price=typeof worldPrice==='function'?worldPrice(w.id):0;
  const p=locked?0:worldProgress(w.id), v=locked?0:seenCount(w.id,true), total=visibleCaps(w.id).length;
  const prev=WORLDS[(worldDeckIndex-1+WORLDS.length)%WORLDS.length]; const next=WORLDS[(worldDeckIndex+1)%WORLDS.length];
  const cover=(typeof ATLAS_IMG!=='undefined' && ATLAS_IMG[w.id])?ATLAS_IMG[w.id]:'';
  deck.innerHTML=`<button class="deck-arrow left" onclick="moveWorldDeck(-1)" data-tip="Mundo anterior">‹</button><div class="deck-card deck-card-main deck-card-v52 ${locked?'deck-locked':''}" style="background:${w.bg};--worldCol:${w.col}" onclick="${locked?`renderShop('${w.id}')`:`openWorld('${w.id}')`}"><div class="deck-side prev">${prev.ico}</div><div class="deck-side next">${next.ico}</div>${cover?`<img class="deck-fullbg" src="${cover}" alt=""><div class="deck-fullbg-scrim"></div><button class="deck-zoom" type="button" aria-label="Ampliar imagen del mundo" onclick="event.stopPropagation(); atlasViewImage('${w.id}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"></circle><path d="M21 21l-4.3-4.3M11 8v6M8 11h6"></path></svg></button><img class="deck-world-cover" src="${cover}" alt="" onclick="event.stopPropagation(); atlasViewImage('${w.id}')">`:''}<div class="deck-main-ico">${locked?'🔒':w.ico}</div><div class="deck-copy"><span>${worldDeckIndex+1}/${WORLDS.length} · ${locked?price+' monedas':(p?'en ruta':'nuevo')}</span><h3>${w.n}</h3><p>${locked?(SHOP_META?.[w.id]?.why||'Mundo desbloqueable con monedas del Atlas.'):w.discipline}</p><small class="deck-teaser">${locked?'Compra este mundo con monedas ganadas explorando.':'Toca para entrar al mapa y descubrir datos para contar.'}</small><div class="bar"><i style="width:${p}%"></i></div><small>${locked?'🔒 bloqueado':v+'/'+total+' tarjetas · '+p+'%'}</small></div></div><button class="deck-arrow right" onclick="moveWorldDeck(1)" data-tip="Mundo siguiente">›</button>`;
  const card=deck.querySelector('.deck-card');
  let sx=0;
  card.addEventListener('touchstart',e=>{sx=e.touches[0].clientX},{passive:true});
  card.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-sx; if(Math.abs(dx)>48) moveWorldDeck(dx<0?1:-1);},{passive:true});
}
function moveWorldDeck(dir){ worldDeckIndex=(worldDeckIndex+dir+WORLDS.length)%WORLDS.length; renderWorldDeck(); playSound('module'); }
function setWorldView(mode,save=true){
  worldViewMode=mode||'deck'; if(save) localStorage.setItem(WORLD_VIEW_KEY,worldViewMode);
  document.getElementById('worldGrid')?.classList.toggle('hidden',worldViewMode==='deck');
  document.getElementById('worldDeck')?.classList.toggle('hidden',worldViewMode!=='deck');
  document.getElementById('gridModeBtn')?.classList.toggle('sel',worldViewMode==='grid');
  document.getElementById('deckModeBtn')?.classList.toggle('sel',worldViewMode==='deck');
}
function renderCertPanel(){
  const box=document.getElementById('certPanel'); if(!box)return; const st=certificateStats(); const earned=st.earned.length;
  const worldCards=WORLDS.map(w=>{ const cert=st.items.find(c=>c.kind==='world' && c.worlds.length===1 && c.worlds[0]===w.id); const score=cert?cert.score:Math.min(100,Math.round(worldProgress(w.id)*.9+(U.quiz[w.id]?.pct||0)*.1)); const ready=score>=80; return `<article class="cert-mini ${ready?'is-earned':''}" data-tip="${w.discipline}"><div class="cert-mini-head"><span class="wm" style="background:${w.col}22">${w.ico}</span><div><b>${w.n}</b><small>${cert?cert.n:'Certificado del mundo'}</small></div></div><div class="cert-mini-meter"><i style="width:${score}%"></i></div><div class="cert-mini-meta"><span>${ready?'Disponible':'En progreso'}</span><span>${score}%</span></div>${ready&&cert?`<button class="cert-download small" onclick="downloadCertificateHTML('${cert.id}')">⬇️ HTML</button>`:''}</article>`; }).join('');
  box.innerHTML=`<div class="cert-panel-head"><div><h4>📜 Certificados</h4><p>${earned} listos · cada mundo suma avance, quiz y logros.</p></div><button class="secondary" onclick="renderCertificates()">Ver todos</button></div><div class="cert-mini-grid">${worldCards}</div>`;
}
function renderFavoritesPanel(){
  const box=document.getElementById('favoritesPanel'); if(!box)return; const favs=U.favs.map(cid=>CAPSULES.find(c=>c.id===cid)).filter(Boolean); box.classList.toggle('hidden',!favs.length); if(!favs.length){box.innerHTML=''; return;}
  box.innerHTML=`<div class="fav-panel-head"><b>💛 Favoritas recientes</b><button class="mini" onclick="renderFavorites()">Ver todas</button></div><div class="favorites-grid">${favs.slice(-4).reverse().map(c=>{const w=worldById(c.w); return `<button class="fav-card" onclick="openFavoriteCard('${c.id}')" data-tip="${w.n}"><span class="fav-world" style="background:${w.col}22">${c.ico}</span><div><b>${c.mapTitle||c.t}</b><small>${w.ico} ${w.n}</small></div><span class="fav-heart">💛</span></button>`}).join('')}</div>`;
}
function getFavoriteList(){ return U.favs.map(cid=>CAPSULES.find(c=>c.id===cid)).filter(Boolean); }
function openFavoriteCard(cid){ const list=getFavoriteList(); const index=list.findIndex(c=>c.id===cid); if(index<0)return; cardContext={mode:'favorites', list:list.map(c=>c.id), index}; const c=list[index]; currentWorld=c.w; U.lastWorld=c.w; saveState(); openCard(cid,{mode:'favorites', list:cardContext.list, index}); }
function openCard(cid,ctx=null){
  const c=CAPSULES.find(x=>x.id===cid); if(!c)return; currentCard=cid; const w=worldById(c.w); if(ctx) cardContext=ctx; else cardContext={mode:'world', list:visibleCaps(c.w).map(x=>x.id), index:visibleCaps(c.w).findIndex(x=>x.id===cid)};
  const done=U.seen.includes(cid), fav=U.favs.includes(cid), next=nextCardAfterCurrent(); const box=document.getElementById('learningCard'); if(!box)return; box.style.borderColor=w.col+'66';
  const subs=(c.subs||[]).slice(0,2).map((s,i)=>`<details class="subcap subcap-v5 compact-sub"><summary><span class="subcap-ico">${s.ico}</span><span><small>${i===0?'Dato extra':'Otra pista'}</small><b>${s.t}</b></span></summary><p>${difficultTerms(s.fact)}</p></details>`).join('');
  const mainAction=done?`<button class="card-action-btn is-done" disabled data-tip="Ya explorada"><span>✅</span><b>Hecho</b></button>`:`<button class="card-action-btn primary-action" onclick="seenCurrent()" data-tip="Marcar como explorada"><span>✅</span><b>Explorar</b></button>`;
  box.innerHTML=`<div class="card-head card-head-v10"><button class="close-x" onclick="closeOverlay('cardOverlay')">✕</button><div class="compact-title-row"><span class="compact-world" style="background:${w.col}22">${w.ico}</span><span class="card-ico-mini">${c.ico}</span><div><small>${cardContext.mode==='favorites'?'Favoritas · ':''}${w.n} · ${RLBL[c.r]}</small><h2>${c.t}</h2></div></div></div><div class="card-body card-body-v10"><div class="fact-box fact-box-v10"><b>${c.factLabel||'💡 ¿Sabías que...?'}</b><p>${difficultTerms(c.fact)}</p></div>${c.sabelotodo?`<div class="sabelo-box"><b>${c.sabelotodoLabel||'🤓 Modo sabelotodo'}</b><p>${difficultTerms(c.sabelotodo)}</p></div>`:''}<div class="subcap-zone-title compact-zone">🧭 Datos extra</div>${subs}<div class="source-box compact-source">📚 ${c.src}</div><div class="card-actions card-actions-v10 card-actions-share-v40">${mainAction}<button class="card-action-btn" onclick="favCurrent()" data-tip="Guardar en favoritas"><span>${fav?'💛':'🤍'}</span><b>${fav?'Favorita':'Guardar'}</b></button><button class="card-action-btn share-action-btn" onclick="window.shareCurrentCard()" data-tip="Compartir tarjeta"><span>${shareIconSvg()}</span><b>Compartir</b></button><button class="card-action-btn" onclick="goNextFromCard()" data-tip="${cardContext.mode==='favorites'?'Siguiente favorita':'Ir a la siguiente tarjeta en el mapa'}"><span>➡️</span><b>${next?'Siguiente':'Mapa'}</b></button></div></div>`;
  document.getElementById('cardOverlay')?.classList.remove('hidden'); playSound('card');
}

function shareIconSvg(){
  return `<svg class="share-nodes-svg" viewBox="0 0 64 64" aria-hidden="true" focusable="false">
    <path d="M25.5 22.5L39.5 14.5M25.5 41.5L39.5 49.5" fill="none" stroke="currentColor" stroke-width="5.5" stroke-linecap="round"/>
    <circle cx="18" cy="32" r="8.5" fill="none" stroke="currentColor" stroke-width="5.5"/>
    <circle cx="47" cy="10" r="8.5" fill="none" stroke="currentColor" stroke-width="5.5"/>
    <circle cx="47" cy="54" r="8.5" fill="none" stroke="currentColor" stroke-width="5.5"/>
  </svg>`;
}
function currentShareText(){
  const c=CAPSULES.find(x=>x.id===currentCard); if(!c) return '';
  const w=worldById(c.w);
  const subs=(c.subs||[]).slice(0,2);
  const lines=[
    `Atlas del Asombro · ${w?.n||'Mundo'}`,
    `${c.t}`,
    '',
    `${c.factLabel||'💡 ¿Sabías que...?'} ${stripHTML(difficultTerms(c.fact||''))}`,
    c.sabelotodo?`${c.sabelotodoLabel||'🤓 Modo sabelotodo'} ${stripHTML(difficultTerms(c.sabelotodo))}`:'',
    subs[0]?`🧭 Dato extra · ${subs[0].t}: ${stripHTML(difficultTerms(subs[0].fact||''))}`:'',
    subs[1]?`🔎 Otra pista · ${subs[1].t}: ${stripHTML(difficultTerms(subs[1].fact||''))}`:'',
    '',
    'Compartido desde Atlas del Asombro'
  ].filter(Boolean);
  return lines.join('\n');
}
function stripHTML(v){
  const div=document.createElement('div'); div.innerHTML=String(v||''); return div.textContent||div.innerText||'';
}
async function copyCurrentShareText(){
  const text=currentShareText();
  try{
    await navigator.clipboard.writeText(text);
    toast('📋 Texto de la tarjeta copiado');
  }catch(e){
    const ta=document.createElement('textarea');
    ta.value=text; document.body.appendChild(ta); ta.select();
    try{ document.execCommand('copy'); toast('📋 Texto copiado'); }
    catch(err){ toast('No se pudo copiar automáticamente'); }
    ta.remove();
  }
}
async function nativeShareCurrentCard(){
  const c=CAPSULES.find(x=>x.id===currentCard); if(!c)return;
  const w=worldById(c.w);
  const text=currentShareText();
  if(navigator.share){
    try{
      await navigator.share({title:`${c.t} · Atlas del Asombro`, text});
      toast('📤 Tarjeta lista para compartir');
    }catch(e){}
  }else{
    await copyCurrentShareText();
  }
}
function shareCurrentCard(){
  const c=CAPSULES.find(x=>x.id===currentCard); if(!c)return;
  const w=worldById(c.w);
  openModal(`<button class="close-x" onclick="closeOverlay('modalOverlay')">✕</button>
    <div class="share-modal-v40">
      <div class="share-modal-head">
        <div class="share-big-ico">${shareIconSvg()}</div>
        <div>
          <small>Compartir tarjeta</small>
          <h2>${escHTML(c.t)}</h2>
          <p>${escHTML(w?.n||'Atlas del Asombro')}</p>
        </div>
      </div>
      <div class="share-preview-card">
        <b>${escHTML(c.factLabel||'💡 ¿Sabías que...?')}</b>
        <p>${escHTML(stripHTML(difficultTerms(c.fact||'')))}</p>
      </div>
      <div class="share-actions-v40">
        <button class="primary" onclick="window.nativeShareCurrentCard()">📤 Compartir</button>
        <button onclick="window.copyCurrentShareText()">📋 Copiar texto</button>
      </div>
      <p class="share-note-v40">Próxima mejora: exportar esta tarjeta como imagen limpia, sin controles, lista para WhatsApp o redes.</p>
    </div>`);
  playSound('module');
}

function nextCardAfterCurrent(){
  if(cardContext.mode==='favorites') return cardContext.list[cardContext.index+1] || null;
  const c=CAPSULES.find(x=>x.id===currentCard); if(!c)return null; const caps=visibleCaps(c.w); const idx=caps.findIndex(x=>x.id===currentCard); return caps[idx+1]?.id||null;
}
function goNextFromCard(){
  const next=nextCardAfterCurrent();
  if(cardContext.mode==='favorites'){
    if(next){ openFavoriteCard(next); } else { closeOverlay('cardOverlay'); renderFavorites(); toast('Llegaste al final de tus favoritas.'); }
    return;
  }
  const c=CAPSULES.find(x=>x.id===currentCard); closeOverlay('cardOverlay'); if(!c)return;
  currentWorld=c.w; if(next){ window.__focusCardId=next; renderMap(); toast('Siguiente tarjeta en el mapa.'); } else { window.__focusTrophy=true; renderMap(); toast('No hay más tarjetas visibles. Mira la copa final.'); }
}
function seenCurrent(){ const result=markSeen(currentCard); if(result.fresh){ playSound('card'); toast(`✨ +${RXP[result.card.r]} XP · tarjeta descubierta`); if(worldProgress(result.card.w)>=80&&!U.giftClaimed[result.card.w]){ playSound('gift'); toast('🎁 ¡Alcanzaste el 80%! Hay un regalo pendiente.',3400); } if(visibleWorldComplete(result.card.w)){ playSound('complete'); toast('🏆 ¡Terminaste las tarjetas visibles! Toca la copa.'); } if(result.newBadges?.length) showBadgeUnlock(result.newBadges[0]); } updateTop(); renderWorlds(); renderFavoritesPanel(); renderMap(); openCard(currentCard,cardContext); }
function favCurrent(){ const fav=toggleFav(currentCard); updateTop(); renderFavoritesPanel(); renderWorlds(); toast(fav?'💛 Guardada en Favoritas':'Favorita retirada'); if(cardContext.mode==='favorites'){ const list=getFavoriteList().map(c=>c.id); const index=list.findIndex(id=>id===currentCard); cardContext={mode:'favorites', list, index:Math.max(0,index)}; } openCard(currentCard,cardContext); }
function showBadgeUnlock(b){ confetti(24); openModal(`<div class="mini-unlock"><div class="mini-unlock-ico">${b.ico}</div><div class="mini-unlock-copy"><h3>${b.type==='medalla'?'Medalla':'Logro'} desbloqueado</h3><b>${b.n}</b><p>${b.desc}</p></div><button class="primary" onclick="closeOverlay('modalOverlay')">Ok</button></div>`); playSound('complete'); }
function renderAwardsHub(){
  openModal(`<button class="close-x" onclick="closeOverlay('modalOverlay')">✕</button><h2>🏅 Logros y medallas</h2><p class="modal-note">Elige una categoría para ver lo desbloqueado.</p><div class="award-hub award-hub-two"><button onclick="renderAchievements('logro')"><span>🌟</span><b>Logros</b><small>${worldBadgeCount('logro')} obtenidos</small></button><button onclick="renderAchievements('medalla')"><span>🏅</span><b>Medallas</b><small>${worldBadgeCount('medalla')} obtenidas</small></button></div>`);
  playSound('module');
}
