/* v46 · certificados realmente funcionales */
function certMainWorldV46(cert){
  const wid=(cert.worlds&&cert.worlds[0])||'cosmos';
  return (typeof worldById==='function'?worldById(wid):null) || {id:'atlas',n:'Atlas del Asombro',ico:'🗺️',col:'#7dc6ff',discipline:'Exploración curiosa'};
}
function certAllWorldsV46(cert){
  return (cert.worlds||[]).map(wid=>typeof worldById==='function'?worldById(wid):null).filter(Boolean);
}
function certThemeV46(cert){
  const main=certMainWorldV46(cert);
  const worlds=certAllWorldsV46(cert);
  const marks=((worlds.map(w=>w.ico).join(' ')||main.ico)+' ✦ ✧ ✨ ●').trim();
  return {main,worlds,marks};
}
function certAssetUrlV46(rel){
  try{
    const base=(typeof ATLAS_PUBLIC_URL!=='undefined'?ATLAS_PUBLIC_URL:(location.origin+'/'));
    return new URL(String(rel||'').replace(/^\.\//,''), base).href;
  }catch(e){
    return rel||'';
  }
}
function certificateHTMLStyleV46(theme,wmUrl){
  return `<style>
  :root{--col:${theme.main.col};--ink:#0f172a;--soft:#475569;--paper:#fffdf8;--bg1:#08101f;--bg2:#13284b;--gold:#d9b45b}
  *{box-sizing:border-box}html,body{margin:0;padding:0}body{font-family:Arial,Helvetica,sans-serif;background:linear-gradient(135deg,var(--bg1),var(--bg2));min-height:100vh;padding:28px;color:var(--ink)}
  .cert{position:relative;max-width:1120px;margin:0 auto;background:linear-gradient(180deg,rgba(255,255,255,.97),rgba(255,251,241,.98));border-radius:34px;padding:44px 46px 38px;overflow:hidden;box-shadow:0 18px 55px rgba(0,0,0,.26);border:2px solid rgba(217,180,91,.42)}
  .frame{position:absolute;inset:16px;border-radius:24px;border:2px solid rgba(217,180,91,.34);pointer-events:none}
  .deco{position:absolute;inset:0;overflow:hidden;pointer-events:none}.deco span{position:absolute;left:var(--x);top:var(--y);font-size:var(--s);opacity:var(--o);color:var(--col);transform:rotate(-12deg)}
  .wm-art{position:absolute;inset:auto 0 110px 0;width:54%;max-width:520px;margin:auto;left:50%;transform:translateX(-50%);opacity:.095;filter:grayscale(.08) saturate(1.1);pointer-events:none}
  .top{display:flex;justify-content:space-between;align-items:center;gap:20px;position:relative;z-index:1}.brand{display:flex;align-items:center;gap:14px}.logo{width:64px;height:64px;border-radius:18px;background:linear-gradient(135deg,var(--col),#ffffff);display:grid;place-items:center;font-size:30px;box-shadow:0 10px 22px rgba(0,0,0,.12)}
  .tag{font-size:14px;font-weight:800;letter-spacing:.18em;text-transform:uppercase;color:var(--col)}.subtitle{font-size:15px;color:var(--soft);font-weight:700}.seal{min-width:88px;height:88px;border-radius:50%;display:grid;place-items:center;font-size:40px;background:radial-gradient(circle at 30% 25%,#fff6d1,#e9c46a 55%,#cc9f33);box-shadow:0 10px 20px rgba(0,0,0,.16);border:3px solid rgba(255,255,255,.75)}
  .title{margin:28px 0 10px;text-align:center;font-size:18px;font-weight:900;letter-spacing:.28em;text-transform:uppercase;color:var(--soft);position:relative;z-index:1}.name{font-size:24px;color:var(--soft);text-align:center;font-weight:700;position:relative;z-index:1}.grant{margin-top:8px;text-align:center;color:var(--soft);font-size:18px;position:relative;z-index:1}.certname{margin:10px auto 8px;text-align:center;font-size:54px;line-height:1.04;max-width:900px;color:#1e293b;position:relative;z-index:1}.desc{max-width:820px;margin:12px auto 10px;text-align:center;font-size:20px;line-height:1.45;color:#334155;position:relative;z-index:1}.worldline{max-width:900px;margin:16px auto 0;padding:12px 18px;border-radius:18px;background:rgba(15,23,42,.04);text-align:center;color:#475569;font-weight:700;position:relative;z-index:1}
  .chips{display:flex;flex-wrap:wrap;justify-content:center;gap:10px;margin:18px 0 24px;position:relative;z-index:1}.chip{padding:10px 14px;border-radius:999px;background:rgba(255,255,255,.8);border:1px solid rgba(15,23,42,.08);font-weight:800;color:#1f2937}
  .center-mark{display:flex;justify-content:center;gap:10px;align-items:center;margin:24px 0 6px;position:relative;z-index:1}.line{height:2px;flex:1;max-width:220px;background:linear-gradient(90deg,transparent,var(--col),transparent)}.medal-mini{font-size:28px}
  .foot{margin-top:30px;display:flex;justify-content:space-between;gap:20px;align-items:end;color:#475569;font-size:14px;position:relative;z-index:1}.sign{font-family:Georgia,'Times New Roman',serif;font-size:30px;color:var(--col)}.watermark-note{margin-top:18px;text-align:center;color:#64748b;font-size:13px;position:relative;z-index:1}
  .printbar{max-width:1120px;margin:16px auto 0;display:flex;gap:10px;justify-content:center;flex-wrap:wrap}.print{border:none;border-radius:16px;padding:12px 18px;background:linear-gradient(135deg,var(--col),#0ea5e9);color:white;font-weight:900;cursor:pointer}.ghost{border:1px solid rgba(255,255,255,.25);border-radius:16px;padding:12px 18px;background:rgba(255,255,255,.14);color:white;font-weight:800;cursor:pointer}
  @page{size:letter landscape;margin:8mm}
    @media print{body{padding:0;background:#fff}.printbar{display:none}.cert{box-shadow:none;max-width:none;border:none;border-radius:0;min-height:100vh;padding:34px 38px}.wm-art{opacity:.07}}
  @media (max-width:820px){body{padding:12px}.cert{padding:28px 18px 24px}.top{align-items:flex-start}.seal{min-width:72px;height:72px;font-size:32px}.certname{font-size:38px}.desc{font-size:17px}.worldline{font-size:15px}.foot{flex-direction:column;align-items:center;text-align:center}.wm-art{width:78%;bottom:180px;opacity:.08}.title{letter-spacing:.14em}}
  </style>`;
}
function certificateHTML(cert){
  const theme=certThemeV46(cert), name=escHTML(U.name||'Explorador');
  const date=new Date().toLocaleDateString('es-CO',{year:'numeric',month:'long',day:'numeric'});
  const worldText=theme.worlds.map(w=>`${w.ico} ${w.n}`).join(' · ') || 'Exploración general del Atlas';
  const score=certificateScore(cert);
  const marks=theme.marks.split(' ');
  const deco=Array.from({length:34},(_,i)=>`<span style="--x:${(i*37)%96}%;--y:${(i*61)%94}%;--s:${18+(i%5)*8}px;--o:${.045+(i%4)*.022}">${marks[i%marks.length]}</span>`).join('');
  const wmKey = theme.main.id && (typeof ATLAS_IMG!=='undefined') ? ATLAS_IMG[theme.main.id] : null;
  const wmUrl = wmKey ? certAssetUrlV46(wmKey) : '';
  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Certificado - ${escHTML(cert.n)}</title>${certificateHTMLStyleV46(theme,wmUrl)}</head><body><main class="cert"><div class="frame"></div><div class="deco">${deco}</div>${wmUrl?`<img class="wm-art" src="${wmUrl}" alt="Marca de agua del mundo">`:''}<div class="top"><div class="brand"><div class="logo">🗺️</div><div><div class="tag">Atlas del Asombro</div><div class="subtitle">Diploma de exploración curiosa</div></div></div><div class="seal">${escHTML(cert.ico||theme.main.ico||'📜')}</div></div><div class="title">Certificado</div><div class="name">${name}</div><div class="grant">ha desbloqueado</div><h1 class="certname">${escHTML(cert.n)}</h1><p class="desc">${escHTML(cert.desc)}</p><div class="worldline">${escHTML(worldText)}</div><div class="chips"><span class="chip">Avance: ${score}%</span><span class="chip">Fecha: ${escHTML(date)}</span><span class="chip">${escHTML(theme.main.discipline||'Curiosidad + constancia')}</span></div><div class="center-mark"><div class="line"></div><div class="medal-mini">${escHTML(cert.ico||theme.main.ico||'🏅')}</div><div class="line"></div></div><div class="foot"><div>Este certificado reconoce el recorrido, la constancia y la curiosidad del explorador dentro del Atlas del Asombro.</div><div class="sign">Atlas del Asombro</div></div><div class="watermark-note">Puedes imprimir este certificado o guardarlo como PDF desde el navegador.</div></main><div class="printbar"><button class="print" onclick="window.print()">🖨️ Imprimir / Guardar PDF</button><button class="ghost" onclick="window.close()">Cerrar</button></div></body></html>`;
}
function downloadCertificateHTML(certId){
  const cert=CERTIFICATES.find(c=>c.id===certId);
  if(!cert) return toast('No encontré ese certificado.');
  const score=certificateScore(cert);
  if(score<80) return toast('Este certificado aún no está listo.');
  const html=certificateHTML({...cert,score});
  const blob=new Blob([html],{type:'text/html;charset=utf-8'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;
  a.download=`certificado-${slug(cert.n)}-${slug(U.name||'explorador')}.html`;
  a.rel='noopener';
  a.style.display='none';
  document.body.appendChild(a);
  a.click();
  setTimeout(()=>{URL.revokeObjectURL(url); a.remove();},1600);
  toast('📜 Certificado HTML descargado.');
}
function openCertificateHTML(certId){
  const cert=CERTIFICATES.find(c=>c.id===certId);
  if(!cert) return toast('No encontré ese certificado.');
  const score=certificateScore(cert);
  if(score<80) return toast('Este certificado aún no está listo.');
  const html=certificateHTML({...cert,score});
  const w=window.open('', '_blank');
  if(!w){
    toast('El navegador bloqueó la vista. Usa Descargar HTML.');
    return;
  }
  w.document.open();
  w.document.write(html);
  w.document.close();
  toast('👀 Vista previa del certificado abierta.');
}
function renderCertificates(){
  const st=certificateStats();
  openModal(`<button class="close-x" onclick="closeOverlay('modalOverlay')">✕</button><h2>📜 Certificados</h2><p class="modal-note">Cuando un certificado está listo, puedes descargarlo como HTML o abrir una vista previa para imprimir/guardar PDF.</p><div class="modal-grid clean-grid awards-compact">${st.items.map(c=>{ const ready=c.score>=80; return `<div class="award-card clean cert-card ${ready?'is-earned':'lock'}"><div class="award-top"><div class="em">${ready?c.ico:'🔒'}</div><span class="pill">${ready?'listo':'avance'}</span></div><h3>${c.n}</h3><p>${c.desc}</p><div class="cert-meter"><i style="width:${c.score}%"></i></div><p>${c.score}%</p>${ready?`<div class="cert-actions-v45"><button class="cert-download" onclick="downloadCertificateHTML('${c.id}')">⬇️ HTML</button><button class="cert-download alt" onclick="openCertificateHTML('${c.id}')">👀 Vista</button></div>`:`<button class="cert-download is-disabled" disabled>🔒 Aún no disponible</button>`}</div>`}).join('')}</div>`);
  playSound('module');
}


window.certificateHTML=certificateHTML; window.downloadCertificateHTML=downloadCertificateHTML; window.openCertificateHTML=openCertificateHTML; window.renderCertificates=renderCertificates;
function renderFavorites(){ const favs=getFavoriteList(); openModal(`<button class="close-x" onclick="closeOverlay('modalOverlay')">✕</button><h2>💛 Favoritas</h2><p class="modal-note">Al abrir una favorita, el botón “siguiente” avanza dentro de esta lista.</p><div class="modal-grid clean-grid awards-compact">${favs.length?favs.map(c=>{const w=worldById(c.w); return `<button class="award-card clean fav-modal" onclick="closeOverlay('modalOverlay'); openFavoriteCard('${c.id}')"><div class="award-top"><span class="em">${c.ico}</span><span class="pill">${w.ico} ${w.n}</span></div><h3>${c.t}</h3><p>${difficultTerms(c.fact).slice(0,118)}${c.fact.length>118?'…':''}</p></button>`}).join(''):`<div class="award-card clean"><div class="em">💛</div><h3>No hay favoritas todavía</h3><p>Marca con el corazón las tarjetas que quieras conservar.</p></div>`}</div>`); playSound('module'); }
function renderProfile(){
  const r=getRankProg();
  openModal(`<button class="close-x" onclick="closeOverlay('modalOverlay')">✕</button><h2>${U.avatar} Perfil de ${U.name}</h2><div class="modal-grid clean-grid awards-compact"><div class="award-card clean"><div class="em">${r.cur.ico}</div><h3>${r.cur.n}</h3><p>${U.xp} XP · ${r.nxt?`faltan ${r.left} XP para ${r.nxt.n}`:'rango máximo'}</p></div><div class="award-card clean"><div class="em">🪙</div><h3>${U.coins} monedas</h3><p>Se obtienen al descubrir tarjetas, regalos y quizzes.</p></div><div class="award-card clean"><div class="em">🗺️</div><h3>${U.seen.length}/${CAPSULES.filter(c=>!c.bonus).length} tarjetas base</h3><p>Las tarjetas bonus amplían los mapas.</p></div><div class="award-card clean"><div class="em">💛</div><h3>${U.favs.length} favoritas</h3><p>Tarjetas guardadas para volver después.</p></div></div><div class="profile-actions"><button class="secondary" onclick="exportProgressJSON()">Exportar backup JSON</button><button class="secondary" onclick="importProgressJSON()">Cargar backup JSON</button><button class="secondary" onclick="renderFavorites()">Ver favoritas</button><button class="secondary" onclick="renderShop()">Tienda</button><button class="secondary" onclick="safeExitToLogin()">Salir al inicio</button><button class="mini" onclick="if(confirm('¿Reiniciar todo el progreso?')) resetState()">Reiniciar progreso</button></div>`);
  playSound('module');
}

function exportProgressJSON(){
  const payload={exportedAt:new Date().toISOString(), profile:{name:U.name, avatar:U.avatar, xp:U.xp, coins:U.coins}, progress:{seen:U.seen, favorites:U.favs, badges:U.badges, gifts:U.giftClaimed, bonusUnlocked:U.bonusUnlocked, trophies:U.trophies, quiz:U.quiz, visitedWorlds:U.visitedWorlds, resources:U.res, shopWorlds:U.shopWorlds||[]}, summary:{certificates:certificateStats(), rank:getRankProg(), worlds:WORLDS.map(w=>({id:w.id,name:w.n,progress:worldProgress(w.id),visibleProgress:visibleWorldProgress(w.id),seen:seenCount(w.id,true)}))}};
  const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download=`atlas-del-asombro-${slug(U.name||'explorador')}-backup.json`;
  a.click();
  setTimeout(()=>URL.revokeObjectURL(a.href),500);
  toast('Backup JSON exportado.');
}

function importProgressJSON(){
  const input=document.createElement('input');
  input.type='file';
  input.accept='application/json,.json';
  input.onchange=async()=>{
    const file=input.files?.[0];
    if(!file) return;
    try{
      const raw=await file.text();
      const data=JSON.parse(raw);
      const next=freshState();
      const pr=data.progress||{};
      const pf=data.profile||{};
      next.name=String(pf.name||data.name||next.name).slice(0,20)||next.name;
      next.avatar=pf.avatar||data.avatar||next.avatar;
      next.xp=Number(pf.xp ?? data.xp ?? next.xp)||0;
      next.coins=Number(pf.coins ?? data.coins ?? next.coins)||0;
      next.seen=Array.isArray(pr.seen)?pr.seen.filter(id=>CAPSULES.some(c=>c.id===id)):[];
      next.favs=Array.isArray(pr.favorites)?pr.favorites.filter(id=>CAPSULES.some(c=>c.id===id)):[];
      next.badges=Array.isArray(pr.badges)?pr.badges:[];
      next.visitedWorlds=Array.isArray(pr.visitedWorlds)?pr.visitedWorlds.filter(id=>WORLDS.some(w=>w.id===id)):[];
      next.quiz=pr.quiz && typeof pr.quiz==='object'?pr.quiz:{};
      next.trophies=Array.isArray(pr.trophies)?pr.trophies.filter(id=>WORLDS.some(w=>w.id===id)):[];
      next.giftClaimed=pr.gifts && typeof pr.gifts==='object'?pr.gifts:{};
      next.bonusUnlocked=pr.bonusUnlocked && typeof pr.bonusUnlocked==='object'?pr.bonusUnlocked:{};
      next.lastWorld=next.visitedWorlds.at(-1)||next.lastWorld;
      next.res={...next.res,...(pr.resources&&typeof pr.resources==='object'?pr.resources:{})};
      next.shopWorlds=Array.isArray(pr.shopWorlds)?pr.shopWorlds.filter(id=>typeof isShopWorld==='function'&&isShopWorld(id)):[];
      U=next; saveState(); updateHome(); closeOverlay('modalOverlay'); showScreen('homeScreen');
      toast('Backup JSON cargado correctamente.');
    }catch(err){ console.error(err); toast('No se pudo cargar el archivo JSON.'); }
  };
  input.click();
}


function safeExitToLogin(){
  openModal(`<button class="close-x" onclick="closeOverlay('modalOverlay')">✕</button><div class="gift-reveal gift-compact"><div class="box">🚪</div><h2>Salir al inicio</h2><p>Antes de volver a la pantalla inicial, puedes descargar una copia JSON de seguridad.</p><div class="profile-actions"><button class="secondary" onclick="exportProgressJSON()">Descargar JSON</button><button class="primary" onclick="closeOverlay('modalOverlay'); showScreen('loginScreen'); toast('Volviste al inicio. Tu avance sigue guardado.')">Salir al inicio</button></div></div>`);
}


function renderShop(focusId=null){
  ensureShopState?.();
  const items=(typeof SHOP_WORLD_IDS!=='undefined'?SHOP_WORLD_IDS:[]).map(id=>worldById(id)).filter(Boolean);
  const currentCoins=U.coins||0;
  const html=items.map(w=>{
    const price=worldPrice(w.id), unlocked=worldUnlocked(w.id), meta=SHOP_META?.[w.id]||{};
    const can=currentCoins>=price;
    return `<article class="shop-card ${unlocked?'is-owned':''} ${focusId===w.id?'focus-shop':''}" style="--worldCol:${w.col}"><div class="shop-ico">${unlocked?w.ico:'🔒'}</div><div class="shop-copy"><span>${meta.tag||'mundo premium'} · ${price} 🪙</span><h3>${w.n}</h3><p>${meta.why||w.discipline}</p><small>${unlocked?'Ya está en tu baraja.':'Completa mundos, quizzes y copas para reunir monedas.'}</small></div><button class="${unlocked?'secondary':'primary'}" onclick="${unlocked?`closeOverlay('modalOverlay'); openWorld('${w.id}')`:`buyWorldFromShop('${w.id}')`}">${unlocked?'Entrar':can?'Comprar':'Faltan '+(price-currentCoins)}</button></article>`;
  }).join('');
  openModal(`<button class="close-x" onclick="closeOverlay('modalOverlay')">✕</button><div class="shop-head"><div><span class="kicker">Tienda del Atlas</span><h2>🛒 Compra mundos con monedas</h2><p>Tienes <b>${currentCoins} monedas</b>. Un mundo completo suele dar cerca de 200 monedas; los mundos premium cuestan entre 320 y 420.</p></div></div><div class="shop-grid">${html}</div><div class="shop-note">Las monedas no compran ventaja: abren nuevas rutas de curiosidad.</div>`);
  playSound('module');
}
function buyWorldFromShop(id){
  const r=buyShopWorld(id);
  toast(r.msg,3200);
  if(r.ok){ confetti(70); playSound('gift'); updateHome(); renderShop(id); }
}

function renderGifts(){ const list=pendingGiftWorlds(); if(!list.length){ toast('No hay regalos pendientes todavía.'); return; } openModal(`<button class="close-x" onclick="closeOverlay('modalOverlay')">✕</button><div class="gift-reveal"><div class="box">🎁</div><h2>Regalos pendientes</h2><p>Abre un regalo para sumar una tarjeta bonus a ese mundo.</p><div class="modal-grid awards-compact" style="margin-top:14px">${list.map(w=>`<button class="award-card clean" onclick="openGift('${w.id}')"><div class="em">${w.ico}</div><h3>${w.n}</h3><p>${worldProgress(w.id)}% completado · reclamar tarjeta</p></button>`).join('')}</div></div>`); playSound('gift'); }
function openGift(wid){ const cap=claimGift(wid); if(!cap)return; confetti(120); playSound('gift'); openModal(`<div class="gift-reveal gift-compact"><div class="box">🎁</div><h2>¡Tarjeta revelada!</h2><p><b>${cap.t}</b></p><p>Se sumó una cápsula bonus al mapa de <b>${worldById(wid).n}</b>.</p><button class="primary big" onclick="closeOverlay('modalOverlay'); openWorld('${wid}'); openCard('${cap.id}')">Abrir bonus</button></div>`); updateTop(); renderWorlds(); renderFavoritesPanel(); }
function claimWorldTrophy(wid){ if(!visibleWorldComplete(wid))return; const first=!U.trophies.includes(wid); if(first){U.trophies.push(wid); U.coins+=50; U.xp+=80; saveState();} confetti(first?110:34); playSound('trophy'); const w=worldById(wid); openModal(`<div class="trophy-modal trophy-modal-v22" style="--trophyCol:${w.col};--trophyBg:${w.col}22"><div class="trophy-burst"><span>🏆</span></div><h2>${first?'¡Copa conquistada!':'Copa ya reclamada'}</h2><p><em>${w.n}</em> quedó completo.</p><div class="trophy-prizes"><span>+80 XP</span><span>+50 🪙</span><span>📜 certificado</span></div><small>${first?'Premios agregados a tu perfil.':'Puedes seguir explorando otros mundos.'}</small><button class="primary big" onclick="closeOverlay('modalOverlay'); showScreen('homeScreen'); updateHome();">Volver a mundos</button></div>`); updateTop(); renderCertPanel(); }
function buildQuiz(wid){ const done=visibleCaps(wid).filter(c=>U.seen.includes(c.id)); if(done.length<4)return null; const pool=[...done].sort(()=>Math.random()-.5).slice(0,Math.min(8,done.length)); const worldTitles=baseCaps(wid).map(c=>c.t); return pool.map(c=>{ const distractors=worldTitles.filter(t=>t!==c.t).sort(()=>Math.random()-.5).slice(0,3); const opts=[c.t,...distractors].sort(()=>Math.random()-.5); const idea=difficultTerms(c.fact).slice(0,125)+(c.fact.length>125?'...':''); return {card:c,q:`¿Qué tarjeta explica esta idea? “${idea}”`,opts,ok:opts.indexOf(c.t),why:'Mira el dato central y busca el título que mejor lo resume.'}; }); }
function openHomeQuiz(){
  let wid=currentWorld || U.lastWorld;
  if(!wid){
    const ready=WORLDS.find(w=>visibleCaps(w.id).filter(c=>U.seen.includes(c.id)).length>=4);
    wid=ready?.id;
  }
  if(!wid){ toast('Explora 4 tarjetas de un mundo para activar un quiz.'); return; }
  currentWorld=wid; U.lastWorld=wid; saveState();
  openQuiz();
}
function openQuiz(){ if(!currentWorld){toast('Primero entra a un mundo.');return;} const quiz=buildQuiz(currentWorld); if(!quiz){toast('Explora al menos 4 tarjetas visibles para abrir el quiz.');return;} quizState={wid:currentWorld,items:quiz,idx:0,score:0,answered:false}; renderQuizQuestion(); }
function renderQuizQuestion(){ const q=quizState.items[quizState.idx]; openModal(`<button class="close-x" onclick="closeOverlay('modalOverlay')">✕</button><h2>🧩 Quiz · ${worldById(quizState.wid).n}</h2><p style="color:var(--muted);font-weight:850">Pregunta ${quizState.idx+1} de ${quizState.items.length}</p><div class="fact-box"><p>${q.q}</p></div><div class="quiz-options">${q.opts.map((o,i)=>`<button onclick="answerQuiz(${i})">${o}</button>`).join('')}</div><div id="quizFeed" class="source-box hidden"></div>`); playSound('module'); }
function answerQuiz(i){ if(quizState.answered)return; quizState.answered=true; const q=quizState.items[quizState.idx]; const btns=[...document.querySelectorAll('.quiz-options button')]; btns.forEach((b,ix)=>{b.disabled=true;if(ix===q.ok)b.classList.add('ok');else if(ix===i)b.classList.add('ng');}); if(i===q.ok){quizState.score++; U.xp+=5; U.coins+=2; playSound('card');} const feed=document.getElementById('quizFeed'); feed.classList.remove('hidden'); feed.innerHTML=(i===q.ok?'✅ Correcto. ':'🧭 Buena intención. ')+q.why+`<br><br><button class="primary" onclick="nextQuiz()">${quizState.idx+1===quizState.items.length?'Ver resultado':'Siguiente'}</button>`; saveState(); updateTop(); }
function nextQuiz(){ quizState.idx++; quizState.answered=false; if(quizState.idx>=quizState.items.length){ registerQuiz(quizState.wid,quizState.score,quizState.items.length); checkBadges(); saveState(); const pct=Math.round(quizState.score/quizState.items.length*100); confetti(pct>=80?90:35); playSound(pct>=80?'complete':'module'); openModal(`<div class="gift-reveal gift-compact"><div class="box">${pct>=80?'🏆':'🧩'}</div><h2>${quizState.score}/${quizState.items.length} correctas</h2><p>${pct>=80?'¡Excelente! Este resultado ayuda a tus certificados.':'Buen avance. Puedes repasar tarjetas y volver a intentar.'}</p><button class="primary big" onclick="closeOverlay('modalOverlay')">Volver</button></div>`); updateTop(); return;} renderQuizQuestion(); }
function updateHome(){ updateTop(); renderWorlds(); renderCertPanel(); renderFavoritesPanel(); }
window.addEventListener('click',e=>{ if(e.target.closest('button,.world-card,.map-node')){ if(e.target.id!=='startBtn') playSound('click'); }});
let pressTimer=null; document.addEventListener('touchstart',e=>{ const tip=e.target.closest('[data-tip]'); if(tip){ pressTimer=setTimeout(()=>toast(tip.dataset.tip,1800),650); }},{passive:true}); document.addEventListener('touchend',()=>clearTimeout(pressTimer),{passive:true});

/* v17 · definiciones breves para niños 8-12 */
function difficultTerms(text){
  let out=String(text||'');
  const defs=[
    ['sistema posicional','sistema posicional (el lugar de un número cambia su valor, como el 2 en 20)'],
    ['fusión nuclear','fusión nuclear (unión de partículas muy pequeñas que libera mucha energía)'],
    ['dióxido de carbono','dióxido de carbono (un gas del aire)'],
    ['fotosíntesis','fotosíntesis (proceso con el que muchas plantas usan luz para fabricar alimento)'],
    ['atmósfera','atmósfera (capa de gases que rodea un planeta)'],
    ['gravedad','gravedad (fuerza que atrae unas cosas hacia otras)'],
    ['probabilidad','probabilidad (qué tan posible es que algo ocurra)'],
    ['evolución','evolución (cambio de los seres vivos durante muchísimas generaciones)'],
    ['neuroplasticidad','neuroplasticidad (capacidad del cerebro para cambiar y aprender)'],
    ['sinapsis','sinapsis (conexión por donde las neuronas se comunican)'],
    ['neuronas','neuronas (células que llevan mensajes en el cerebro y los nervios)'],
    ['neurona','neurona (célula que lleva mensajes en el cerebro y los nervios)'],
    ['moléculas','moléculas (grupos de átomos unidos)'],
    ['molécula','molécula (grupo de átomos unidos)'],
    ['átomos','átomos (piezas muy pequeñas de la materia)'],
    ['átomo','átomo (pieza muy pequeña de la materia)'],
    ['ADN','ADN (instrucciones internas de los seres vivos)'],
    ['resiliencia','resiliencia (capacidad de recuperarse ante cambios o problemas)'],
    ['salinidad','salinidad (cantidad de sal en el agua)'],
    ['tectónicas','tectónicas (relacionadas con placas enormes de roca que se mueven muy despacio)'],
    ['pH','pH (medida de acidez)'],
    ['enzimas','enzimas (proteínas que aceleran reacciones del cuerpo)'],
    ['catalizadores','catalizadores (sustancias que aceleran reacciones sin gastarse rápido)'],
    ['bioluminiscencia','bioluminiscencia (luz producida por seres vivos)'],
    ['micorrizas','micorrizas (alianza entre raíces y hongos del suelo)'],
    ['domesticación','domesticación (cambio de especies por convivencia y selección humana durante generaciones)'],
    ['patrimonio','patrimonio (herencia cultural o natural que una comunidad cuida)']
  ];
  for(const [term,repl] of defs){
    const escaped=term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    if(out.toLowerCase().includes(repl.toLowerCase())) continue;
    out=out.replace(new RegExp(escaped,'gi'),repl);
  }
  return out;
}

