function bind(id, handler){
  const el=document.getElementById(id);
  if(el) el.onclick=handler;
  return el;
}
function init(){
  loadState();
  makeParticles('loginParticles',90);
  makeParticles('homeParticles',120);

  const row=document.getElementById('avatarRow');
  if(row){
    row.innerHTML=AVATARS.map((a,i)=>`<button class="avatar-btn ${i===0?'sel':''}" data-av="${a}">${a}</button>`).join('');
    row.addEventListener('click',e=>{
      const b=e.target.closest('.avatar-btn');
      if(!b) return;
      document.querySelectorAll('.avatar-btn').forEach(x=>x.classList.remove('sel'));
      b.classList.add('sel');
      U.avatar=b.dataset.av;
    });
  }

  bind('startBtn',()=>{
    U.name=(document.getElementById('nameInput').value||'Explorador').replace(/[^a-zA-ZáéíóúÁÉÍÓÚüÜñÑ\s]/g,'').trim().slice(0,20)||'Explorador';
    Sound.intro();
    saveState();
    updateHome();
    showScreen('homeScreen');
  });
  bind('continueBtn',()=>{ if(U.lastWorld) openWorld(U.lastWorld); else toast('Elige primero un mundo para comenzar.'); });
  bind('giftBtn',renderGifts);
  bind('achievementsBtn',renderAwardsHub);
  bind('certificatesBtn',renderCertificates);
  bind('rewardsBtn',renderGifts);
  bind('shopBtn',renderShop);
  bind('favoritesBtn',renderFavorites);
  bind('homeQuizBtn',()=>window.openLearningGamesChoice?window.openLearningGamesChoice():openHomeQuiz());
  bind('profileBtn',renderProfile);
  bind('exitBtn',safeExitToLogin);
  bind('gridModeBtn',()=>setWorldView('grid'));
  bind('deckModeBtn',()=>setWorldView('deck'));
  bind('homeAvatar',renderProfile);
  bind('backHome',()=>{ showScreen('homeScreen'); updateHome(); playSound('module'); });
  bind('quizBtn',openQuiz);
  bind('mapGamesBtn',()=>window.openLearningGamesChoice?window.openLearningGamesChoice():openQuiz());
  bind('navWorlds',()=>{ showScreen('homeScreen'); updateHome(); playSound('module'); });
  bind('navQuiz',()=>window.openLearningGamesChoice?window.openLearningGamesChoice():openQuiz());
  bind('navAwards',renderAwardsHub);
  bind('navProfile',renderProfile);

  const cardOverlay=document.getElementById('cardOverlay');
  if(cardOverlay) cardOverlay.addEventListener('click',e=>{ if(e.target.id==='cardOverlay') closeOverlay('cardOverlay'); });
  const modalOverlay=document.getElementById('modalOverlay');
  if(modalOverlay) modalOverlay.addEventListener('click',e=>{ if(e.target.id==='modalOverlay') closeOverlay('modalOverlay'); });

  if(U.name){
    const inp=document.getElementById('nameInput');
    if(inp) inp.value=U.name;
    document.querySelectorAll('.avatar-btn').forEach(b=>b.classList.toggle('sel',b.dataset.av===U.avatar));
    updateHome();
    showScreen('homeScreen');
  }
}
document.addEventListener('DOMContentLoaded',()=>{ init(); /* PWA retirada en v47 */ });




