    const theme = {main, worlds};
    const worldText = worlds.map(w => `${w.ico} ${w.n}`).join(' · ') || main.n || 'Atlas del Asombro';
    const score = (typeof certificateScore === 'function') ? certificateScore(cert) : (cert.score || 100);
