/* v54 · tarjeta para compartir con altura dinámica y footer icónico */
(function shareCardDynamicV54(){
  function shareDataV54(){
    if(typeof currentCard==='undefined' || !currentCard || typeof CAPSULES==='undefined') return null;
    const c = CAPSULES.find(x=>x.id===currentCard); if(!c) return null;
    const w = (typeof worldById==='function') ? worldById(c.w) : null;
    const atlas = (typeof ATLAS_IMG!=='undefined') ? ATLAS_IMG : {};
    const imgSrc = atlas[currentCard] || atlas[c.id] || '';
    return {
      card:c,
      world:w,
      imgSrc,
      factLabel:c.factLabel||'💡 ¿Sabías que...?',
      fact:String(c.fact||'').replace(/\s+/g,' ').trim(),
      sabelotodoLabel:c.sabelotodoLabel||'🤓 Modo sabelotodo',
      sabelotodo:String(c.sabelotodo||'').replace(/\s+/g,' ').trim()
    };
  }
  function wrapLinesV54(ctx, text, maxWidth){
    const words=String(text||'').split(/\s+/).filter(Boolean);
    const lines=[]; let line='';
    for(const word of words){
      const test=line?line+' '+word:word;
      if(ctx.measureText(test).width<=maxWidth){ line=test; }
      else{ if(line) lines.push(line); line=word; }
    }
    if(line) lines.push(line);
    return lines.length?lines:[''];
  }
  function paragraphMetricsV54(ctx, text, maxWidth, lineHeight){
    const lines=wrapLinesV54(ctx,text,maxWidth);
    return { lines, height: lines.length*lineHeight };
  }
  function roundRectPathV54(ctx,x,y,w,h,r){
    const rr=Math.min(r,w/2,h/2);
    ctx.beginPath();
    ctx.moveTo(x+rr,y);
    ctx.arcTo(x+w,y,x+w,y+h,rr);
    ctx.arcTo(x+w,y+h,x,y+h,rr);
    ctx.arcTo(x,y+h,x,y,rr);
    ctx.arcTo(x,y,x+w,y,rr);
    ctx.closePath();
  }
  function drawRoundRectV54(ctx,x,y,w,h,r,fill,stroke=null,sw=1){
    roundRectPathV54(ctx,x,y,w,h,r);
    if(fill){ ctx.fillStyle=fill; ctx.fill(); }
    if(stroke){ ctx.strokeStyle=stroke; ctx.lineWidth=sw; ctx.stroke(); }
  }
  function drawParagraphV54(ctx, lines, x, y, lineHeight, color){
    ctx.fillStyle=color;
    lines.forEach((ln,i)=>ctx.fillText(ln, x, y + i*lineHeight));
    return lines.length;
  }
  function fitTextV54(ctx, text, maxWidth){
    let t=String(text||'');
    if(ctx.measureText(t).width<=maxWidth) return t;
    while(t.length>3 && ctx.measureText(t+'…').width>maxWidth){ t=t.slice(0,-1).trim(); }
    return t+'…';
  }
  function rarityMetaV54(r){
    const m={
      common:['🟢','Común'], rare:['🔵','Rara'], epic:['🟣','Épica'], legendary:['🟡','Legendaria'], gift:['🎁','Regalo']
    };
    return m[r] || ['✨',(typeof RLBL!=='undefined'&&RLBL[r])?RLBL[r]:'Cápsula'];
  }
  function loadImageV54(src){
    return new Promise((resolve,reject)=>{
      const img=new Image();
      img.crossOrigin='anonymous';
      img.onload=()=>resolve(img);
      img.onerror=reject;
      img.src=src;
    });
  }
  async function renderShareCardBlobV54(mode='full'){
    const d=shareDataV54();
    if(!d) throw new Error('No current card');

    const W=1080;
    const shellX=54, shellY=52, shellW=W-108;
    const contentX=92, sectionW=W-184;
    const temp=document.createElement('canvas');
    temp.width=W; temp.height=2000;
    const ctx=temp.getContext('2d');

    // measure title
    ctx.font='900 52px Arial, sans-serif';
    const titleLines=wrapLinesV54(ctx, d.card.t || '', W-184).slice(0,3);
    const titleBottom = 230 + (titleLines.length-1)*56;
    const topAfterTitle = 250 + (titleLines.length-1)*56;

    const imgBoxY = topAfterTitle + 28;
    const imgBoxH = mode==='short' ? 460 : 500;
    let y = imgBoxY + imgBoxH + 34;

    // measure fact section
    ctx.font='700 31px Arial, sans-serif';
    const factMetrics=paragraphMetricsV54(ctx, d.fact, sectionW-52, 40);
    const factBoxH=Math.max(mode==='short'?180:220, 120 + factMetrics.height + 24);
    y += factBoxH + 22;

    let sabelotodoMetrics=null, sabelotodoBoxH=0;
    if(mode!=='short' && d.sabelotodo){
      ctx.font='700 29px Arial, sans-serif';
      sabelotodoMetrics=paragraphMetricsV54(ctx, d.sabelotodo, sectionW-52, 38);
      sabelotodoBoxH=Math.max(190, 120 + sabelotodoMetrics.height + 24);
      y += sabelotodoBoxH + 22;
    }

    const iconRailH = mode==='short' ? 106 : 120;
    const footerH = 58;
    const bottomPad = 84;
    const H = Math.max(mode==='short'?1260:1420, y + iconRailH + 18 + footerH + bottomPad);

    const canvas=document.createElement('canvas');
    canvas.width=W; canvas.height=H;
    const c=canvas.getContext('2d');

    // Background
    const grad=c.createLinearGradient(0,0,W,H);
    grad.addColorStop(0,'#08101f');
    grad.addColorStop(.5,'#101b35');
    grad.addColorStop(1,'#12284a');
    c.fillStyle=grad; c.fillRect(0,0,W,H);
    const g1=c.createRadialGradient(160,140,10,160,140,300);
    g1.addColorStop(0,'rgba(34,211,238,.20)'); g1.addColorStop(1,'rgba(34,211,238,0)');
    c.fillStyle=g1; c.fillRect(0,0,W,H);
    const g2=c.createRadialGradient(W-180,220,10,W-180,220,340);
    g2.addColorStop(0,'rgba(124,111,253,.20)'); g2.addColorStop(1,'rgba(124,111,253,0)');
    c.fillStyle=g2; c.fillRect(0,0,W,H);

    drawRoundRectV54(c,shellX,shellY,shellW,H-104,42,'rgba(255,255,255,.08)','rgba(255,255,255,.12)',2);

    // top brand
    c.fillStyle='rgba(191,232,255,.95)';
    c.font='700 28px Arial, sans-serif';
    c.fillText('Atlas del Asombro', 92, 102);

    // world pill
    drawRoundRectV54(c,92,126,420,44,22,'rgba(255,255,255,.10)','rgba(255,255,255,.12)',1.5);
    c.fillStyle='#dff8ff';
    c.font='700 22px Arial, sans-serif';
    c.fillText((d.world?.ico?d.world.ico+'  ':'') + (d.world?.n||'Mundo'), 110, 155);

    // title
    c.fillStyle='#ffffff';
    c.font='900 52px Arial, sans-serif';
    titleLines.forEach((ln,i)=>c.fillText(ln,92,230 + i*56));

    // image box
    drawRoundRectV54(c,92,imgBoxY,W-184,imgBoxH,34,'rgba(255,255,255,.06)','rgba(255,255,255,.10)',1.5);
    try{
      if(d.imgSrc){
        const img=await loadImageV54(d.imgSrc);
        const x=104, y0=imgBoxY+12, w=W-208, h=imgBoxH-24;
        c.save(); roundRectPathV54(c,x,y0,w,h,28); c.clip();
        const scale=Math.max(w/img.width,h/img.height);
        const dw=img.width*scale, dh=img.height*scale;
        const dx=x+(w-dw)/2, dy=y0+(h-dh)/2;
        c.drawImage(img,dx,dy,dw,dh);
        c.restore();
      }
    }catch(e){
      c.fillStyle='rgba(255,255,255,.08)';
      c.fillRect(104,imgBoxY+12,W-208,imgBoxH-24);
      c.fillStyle='rgba(255,255,255,.75)';
      c.font='700 30px Arial, sans-serif';
      c.fillText('Imagen de la cápsula', 360, imgBoxY+250);
    }

    let yy = imgBoxY + imgBoxH + 34;

    // fact
    drawRoundRectV54(c,92,yy,sectionW,factBoxH,26,'rgba(255,255,255,.07)','rgba(255,255,255,.10)',1.2);
    c.fillStyle='#bfe8ff';
    c.font='900 24px Arial, sans-serif';
    c.fillText(d.factLabel, 118, yy+42);
    c.fillStyle='#f4f9ff';
    c.font='700 31px Arial, sans-serif';
    drawParagraphV54(c,factMetrics.lines,118,yy+88,40,'#f4f9ff');
    yy += factBoxH + 22;

    // sabelotodo
    if(mode!=='short' && d.sabelotodo){
      drawRoundRectV54(c,92,yy,sectionW,sabelotodoBoxH,26,'rgba(125,211,252,.08)','rgba(125,211,252,.18)',1.2);
      c.fillStyle='#a7f3ff';
      c.font='900 24px Arial, sans-serif';
      c.fillText(d.sabelotodoLabel, 118, yy+42);
      c.fillStyle='#edf4ff';
      c.font='700 29px Arial, sans-serif';
      drawParagraphV54(c,sabelotodoMetrics.lines,118,yy+88,38,'#edf4ff');
      yy += sabelotodoBoxH + 22;
    }

    // icon rail panel
    const railY=yy;
    drawRoundRectV54(c,92,railY,sectionW,iconRailH,24,'rgba(255,255,255,.055)','rgba(255,255,255,.09)',1);
    const [rIco, rLabel] = rarityMetaV54(d.card.r);
    const chips=[
      {ico:d.world?.ico||'🗺️', label:'Mundo', text:d.world?.n||'Atlas del Asombro'},
      {ico:d.card.ico||'✨', label:'Tema', text:d.card.mapTitle||d.card.t||'Cápsula'},
      {ico:rIco, label:'Tipo', text:rLabel}
    ];
    const gap=16, chipY=railY+18, chipH=iconRailH-36;
    const chipW=(sectionW - 32 - gap*2)/3;
    chips.forEach((chip,i)=>{
      const x=108 + i*(chipW+gap);
      drawRoundRectV54(c,x,chipY,chipW,chipH,20,'rgba(255,255,255,.07)','rgba(255,255,255,.10)',1);
      c.font='700 30px Arial, sans-serif'; c.fillStyle='#ffffff'; c.fillText(chip.ico, x+18, chipY+38);
      c.fillStyle='rgba(183,232,255,.88)'; c.font='700 18px Arial, sans-serif'; c.fillText(chip.label, x+58, chipY+24);
      c.fillStyle='#f5fbff'; c.font='700 22px Arial, sans-serif'; c.fillText(fitTextV54(c, chip.text, chipW-74), x+58, chipY+52);
    });
    yy += iconRailH + 18;

    // footer
    drawRoundRectV54(c,92,yy,sectionW,58,22,'rgba(255,255,255,.06)','rgba(255,255,255,.09)',1);
    c.fillStyle='rgba(237,244,255,.82)';
    c.font='700 22px Arial, sans-serif';
    c.fillText('Descubre más mundos curiosos en Atlas del Asombro', 118, yy+38);

    return await new Promise((resolve,reject)=>{
      canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('No blob')), 'image/png');
    });
  }
  async function downloadShareCardImageV54(mode='full'){
    const d=shareDataV54(); if(!d){ if(typeof toast==='function') toast('Abre una tarjeta para compartirla'); return; }
    const blob=await renderShareCardBlobV54(mode);
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    const slug=(d.card.t||'tarjeta').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^\w]+/g,'-').replace(/^-+|-+$/g,'');
    a.href=url; a.download=`atlas-${slug}-${mode==='short'?'corta':'completa'}.png`;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>URL.revokeObjectURL(url),1200);
    if(typeof toast==='function') toast('🖼️ Imagen descargada');
  }
  async function shareCurrentCardImageV54(mode='full'){
    const d=shareDataV54(); if(!d){ if(typeof toast==='function') toast('Abre una tarjeta para compartirla'); return; }
    const blob=await renderShareCardBlobV54(mode);
    const slug=(d.card.t||'tarjeta').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^\w]+/g,'-').replace(/^-+|-+$/g,'');
    const file=new File([blob], `atlas-${slug}.png`, {type:'image/png'});
    if(navigator.share && navigator.canShare && navigator.canShare({files:[file]})){
      try{
        await navigator.share({files:[file], title:`${d.card.t} · Atlas del Asombro`, text:`${d.world?.n||'Atlas del Asombro'}`});
        if(typeof toast==='function') toast('📤 Imagen lista para compartir');
        return;
      }catch(e){}
    }
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    a.href=url; a.download=file.name;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>URL.revokeObjectURL(url),1200);
    if(typeof toast==='function') toast('Tu dispositivo no comparte archivos directamente. Se descargó la imagen.');
  }
  window.renderShareCardBlob = renderShareCardBlobV54;
  window.downloadShareCardImage = downloadShareCardImageV54;
  window.shareCurrentCardImage = shareCurrentCardImageV54;
})();

/* ============================================================
   ATLAS DEL ASOMBRO · Bloque de JUEGOS (v54-games, aditivo)
   No modifica nada existente: usa los globales del propio app.js
   (U, WORLDS, baseCaps, worldById, ATLAS_IMG, saveState, toast,
   confetti, playSound, checkBadges). Si algo falta, degrada con
   guardas. Juegos: Sopa de palabras + Memoria. 100% responsive.
   ============================================================ */
(function atlasGames(){
  "use strict";
  function G(name){ try{ return (typeof window!=='undefined' && window[name]!==undefined)? window[name] : eval(name); }catch(e){ return undefined; } }
  function hasFn(n){ return typeof G(n)==='function'; }
  function sound(k){ try{ if(hasFn('playSound')) playSound(k); }catch(e){} }
  function say(m){ try{ if(hasFn('toast')) toast(m); }catch(e){} }
  function party(n){ try{ if(hasFn('confetti')) confetti(n||80); }catch(e){} }
  function save(){ try{ if(hasFn('saveState')) saveState(); }catch(e){} }
  function caps(wid){ try{ if(hasFn('baseCaps')) return baseCaps(wid); }catch(e){} return (typeof CAPSULES!=='undefined')?CAPSULES.filter(function(c){return c.w===wid;}):[]; }
  function worlds(){ return (typeof WORLDS!=='undefined')?WORLDS:[]; }
  function wById(id){ try{ if(hasFn('worldById')) return worldById(id); }catch(e){} return worlds().find(function(w){return w.id===id;}); }
  function img(id){ var A=(typeof ATLAS_IMG!=='undefined')?ATLAS_IMG:(window.ATLAS_IMG||{}); return A[id]; }
  function state(){ return (typeof U!=='undefined')?U:(window.U||null); }

  var PALETTE=['#7c6ffd','#38bdf8','#4ade80','#f7c948','#f472b6','#fb923c','#22d3ee','#a78bfa'];
  function randInt(a,b){ return Math.floor(Math.random()*(b-a+1))+a; }
  function shuffle(a){ for(var i=a.length-1;i>0;i--){ var j=(Math.random()*(i+1))|0; var t=a[i];a[i]=a[j];a[j]=t; } return a; }
  function normWord(s){ return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z]/g,''); }

  /* ---------- recompensas ---------- */
  function ensureGameState(){ var u=state(); if(!u) return null; if(!u.games) u.games={done:{}}; if(!u.games.done) u.games.done={}; return u.games; }
  function award(key, xp, coins){
    var u=state(); if(!u) return {xp:0,coins:0};
    var g=ensureGameState();
    var first = !g.done[key];
    var ax = first?xp:Math.ceil(xp/2);
    var ac = first?coins:Math.ceil(coins/2);
    u.xp=(u.xp||0)+ax; u.coins=(u.coins||0)+ac; g.done[key]=(g.done[key]||0)+1;
    try{ if(hasFn('checkBadges')) checkBadges(); }catch(e){}
    save();
    try{ if(hasFn('renderHome')) renderHome(); }catch(e){}
    try{ if(hasFn('renderHUD')) renderHUD(); }catch(e){}
    return {xp:ax, coins:ac, first:first};
  }

  /* ---------- palabras por mundo ---------- */
  var STOP={DEL:1,LA:1,LAS:1,LOS:1,DE:1,EL:1,EN:1,CON:1,UNA:1,UNO:1,POR:1,QUE:1,SUS:1,SU:1,UN:1,Y:1,AL:1,LO:1,ESE:1,ESA:1,ESTE:1,ESTA:1,PARA:1};
  function wordsForWorld(wid, count, maxLen){
    var pool=[]; caps(wid).forEach(function(c){
      String(c.t||'').split(/\s+/).forEach(function(w){ var n=normWord(w); if(n.length>=3 && n.length<=maxLen && !STOP[n]) pool.push(n); });
    });
    var seen={},uniq=[]; pool.forEach(function(w){ if(!seen[w]){seen[w]=1;uniq.push(w);} });
    shuffle(uniq);
    return uniq.slice(0, count);
  }

  /* ---------- overlay / router ---------- */
  var built=false, view='hub', ctx={};
  function build(){
    if(built) return; built=true;
    var o=document.createElement('div'); o.id='agOverlay'; o.className='ag-overlay ag-hidden';
    o.innerHTML=''
      +'<div class="ag-shell">'
      +'  <div class="ag-bar"><button class="ag-back" type="button" aria-label="Atrás">‹</button>'
      +'    <div class="ag-titles"><div class="ag-title" id="agTitle">Juegos</div><div class="ag-sub" id="agSub"></div></div>'
      +'    <button class="ag-close" type="button" aria-label="Cerrar">✕</button></div>'
      +'  <div class="ag-body" id="agBody"></div>'
      +'</div>';
    document.body.appendChild(o);
    o.addEventListener('click',function(e){ if(e.target===o) close(); });
    o.querySelector('.ag-close').addEventListener('click',close);
    o.querySelector('.ag-back').addEventListener('click',onBack);
    document.addEventListener('keydown',function(e){ if(e.key==='Escape' && isOpen()) close(); });
  }
  function isOpen(){ var o=document.getElementById('agOverlay'); return o && !o.classList.contains('ag-hidden'); }
  function open(){ build(); document.getElementById('agOverlay').classList.remove('ag-hidden'); sound('start'); showHub(); }
  function close(){ var o=document.getElementById('agOverlay'); if(o) o.classList.add('ag-hidden'); teardownGame(); }
  function setHead(title,sub,showBack){ var t=document.getElementById('agTitle'),s=document.getElementById('agSub'),b=document.querySelector('#agOverlay .ag-back'); if(t)t.textContent=title; if(s)s.textContent=sub||''; if(b)b.style.visibility=showBack?'visible':'hidden'; }
  function body(){ return document.getElementById('agBody'); }
  function onBack(){ if(view==='diff') showPicker(ctx.game); else if(view==='picker') showHub(); else if(view==='game') showDiff(ctx.game, ctx.world); else showHub(); }

  /* ---------- HUB ---------- */
  var GAMES=[
    {id:'sopa', name:'Sopa de palabras', ico:'🔤', desc:'Encuentra las palabras escondidas', ready:true},
    {id:'memoria', name:'Memoria', ico:'🧠', desc:'Halla las parejas de imágenes', ready:true},
    {id:'rompe', name:'Rompecabezas', ico:'🧩', desc:'Arma la imagen del mundo', ready:true},
    {id:'busca', name:'Busca y encuentra', ico:'🔭', desc:'Encuentra a los personajes', ready:true}
  ];
  function showHub(){
    teardownGame(); view='hub'; setHead('Juegos','Refuerza lo que exploras',false);
    var h='<div class="ag-grid ag-hub">';
    GAMES.forEach(function(g){
      h+='<button class="ag-tile'+(g.ready?'':' ag-soon')+'" '+(g.ready?'data-game="'+g.id+'"':'disabled')+'>'
        +'<span class="ag-tile-ico">'+g.ico+'</span><span class="ag-tile-name">'+g.name+'</span>'
        +'<span class="ag-tile-desc">'+g.desc+'</span>'+(g.ready?'':'<span class="ag-badge-soon">Pronto</span>')+'</button>';
    });
    h+='<button class="ag-tile ag-premium-tile" data-premium-games="1"><span class="ag-tile-ico">🧩</span><span class="ag-tile-name">Conecta el Asombro</span><span class="ag-tile-desc">Juego premium · comprar o jugar</span></button>';
    h+='<button class="ag-tile ag-premium-tile" data-premium-games="1"><span class="ag-tile-ico">🧠</span><span class="ag-tile-name">Memoria de Mundos</span><span class="ag-tile-desc">Juego premium · comprar o jugar</span></button>';
    h+='</div>';
    body().innerHTML=h;
    body().querySelectorAll('[data-game]').forEach(function(b){ b.addEventListener('click',function(){ showPicker(b.getAttribute('data-game')); }); });
    body().querySelectorAll('[data-premium-games]').forEach(function(b){ b.addEventListener('click',function(){ if(window.openPremiumGamesHub) window.openPremiumGamesHub(); else if(window.renderShop) renderShop(); }); });
  }

  /* ---------- PICKER de mundo ---------- */
  function showPicker(game){
    teardownGame(); view='picker'; ctx.game=game; setHead('Elige un mundo','',true);
    var list=worlds().slice();
    var h='<div class="ag-grid ag-worlds">';
    list.forEach(function(w){
      var cover=img(w.id);
      h+='<button class="ag-world" data-w="'+w.id+'" style="--wc:'+(w.col||'#7c6ffd')+'">'
        +(cover?'<img class="ag-world-img" src="'+cover+'" alt="">':'<span class="ag-world-ico">'+(w.ico||'🌍')+'</span>')
        +'<span class="ag-world-name">'+(w.n||'Mundo')+'</span></button>';
    });
    h+='</div>';
    body().innerHTML=h;
    body().querySelectorAll('[data-w]').forEach(function(b){ b.addEventListener('click',function(){ var ww=b.getAttribute('data-w'); if(game==='busca'){ startBusca(ww); } else { showDiff(game, ww); } }); });
  }

  /* ---------- DIFICULTAD ---------- */
  var DIFF={
    sopa:[{k:'facil',n:'Fácil',meta:'8×8 · 5 palabras',N:8,words:5,xp:30,coins:6},
          {k:'medio',n:'Medio',meta:'10×10 · 7 palabras',N:10,words:7,xp:50,coins:10},
          {k:'dificil',n:'Difícil',meta:'12×12 · 8 palabras',N:12,words:8,xp:80,coins:16}],
    memoria:[{k:'facil',n:'Fácil',meta:'6 parejas',pairs:6,xp:24,coins:5},
             {k:'medio',n:'Medio',meta:'8 parejas',pairs:8,xp:40,coins:8},
             {k:'dificil',n:'Difícil',meta:'10 parejas',pairs:10,xp:60,coins:12}],
    rompe:[{k:'facil',n:'Fácil',meta:'8 piezas (2×4)',rows:2,cols:4,xp:30,coins:6},
           {k:'medio',n:'Medio',meta:'16 piezas (4×4)',rows:4,cols:4,xp:55,coins:11},
           {k:'dificil',n:'Experto',meta:'32 piezas (4×8)',rows:4,cols:8,xp:90,coins:18}]
  };
  function showDiff(game, wid){
    teardownGame(); view='diff'; ctx.game=game; ctx.world=wid;
    var w=wById(wid)||{}; setHead((w.n||'Mundo'),'Elige la dificultad',true);
    var opts=DIFF[game]||[];
    var h='<div class="ag-grid ag-diff">';
    opts.forEach(function(o){
      h+='<button class="ag-diff-btn" data-k="'+o.k+'"><span class="ag-diff-name">'+o.n+'</span><span class="ag-diff-meta">'+o.meta+'</span>'
        +'<span class="ag-diff-reward">+'+o.xp+' XP · +'+o.coins+' 🪙</span></button>';
    });
    h+='</div>';
    body().innerHTML=h;
    body().querySelectorAll('[data-k]').forEach(function(b){ b.addEventListener('click',function(){
      var conf=opts.find(function(x){return x.k===b.getAttribute('data-k');});
      if(game==='sopa') startSopa(wid, conf); else if(game==='memoria') startMemoria(wid, conf); else if(game==='rompe') startRompe(wid, conf);
    }); });
  }

  /* ---------- resultado ---------- */
  function showResult(wid, conf, game, extra){
    view='result';
    var key=game+':'+wid+':'+conf.k;
    var r=award(key, conf.xp, conf.coins);
    party(120);
    var w=wById(wid)||{};
    setHead('¡Lo lograste!','',true);
    var h='<div class="ag-result">'
      +'<div class="ag-result-medal">🏆</div>'
      +'<div class="ag-result-title">¡Completaste '+GAMELABEL(game)+'!</div>'
      +'<div class="ag-result-sub">'+(w.n||'')+' · '+conf.n+'</div>'
      +(extra?'<div class="ag-result-extra">'+extra+'</div>':'')
      +'<div class="ag-result-reward">+'+r.xp+' XP &nbsp;·&nbsp; +'+r.coins+' 🪙'+(r.first?'':' <span class="ag-rep">(repetición)</span>')+'</div>'
      +'<div class="ag-result-actions"><button class="ag-btn ag-btn-2" id="agAgain">Jugar otra vez</button><button class="ag-btn ag-btn-1" id="agHub">Más juegos</button></div>'
      +'</div>';
    body().innerHTML=h;
    document.getElementById('agAgain').addEventListener('click',function(){ if(game==='sopa') startSopa(wid,conf); else startMemoria(wid,conf); });
    document.getElementById('agHub').addEventListener('click',showHub);
  }

  /* ====================================================
     JUEGO 1 · SOPA DE PALABRAS
     ==================================================== */
  var sopaState=null;
  function startSopa(wid, conf){
    teardownGame(); view='game'; ctx.game='sopa'; ctx.world=wid;
    var w=wById(wid)||{};
    var N=conf.N;
    var words=wordsForWorld(wid, conf.words, N);
    if(words.length<3){ say('Este mundo aún no tiene suficientes palabras.'); showPicker('sopa'); return; }
    var puzzle=buildWordSearch(words, N);
    setHead((w.n||'Mundo'),'Sopa de palabras · '+conf.n,true);
    var acc=w.col||'#7c6ffd';
    var h='<div class="ag-sopa" style="--ag-acc:'+acc+'">'
      +'<div class="ag-grid-wrap"><div class="ag-board" id="agBoard" style="--n:'+N+'"></div></div>'
      +'<div class="ag-wordlist" id="agWords"></div></div>';
    body().innerHTML=h;
    var board=document.getElementById('agBoard');
    var cellEls=[];
    for(var r=0;r<N;r++){ cellEls[r]=[]; for(var c=0;c<N;c++){ var d=document.createElement('div'); d.className='ag-cell'; d.dataset.r=r; d.dataset.c=c; d.textContent=puzzle.grid[r][c]; board.appendChild(d); cellEls[r][c]=d; } }
    var wl=document.getElementById('agWords');
    puzzle.placed.forEach(function(p,i){ p.color=PALETTE[i%PALETTE.length]; var s=document.createElement('span'); s.className='ag-wchip'; s.dataset.word=p.word; s.textContent=p.word; wl.appendChild(s); });
    sopaState={wid:wid, conf:conf, N:N, grid:puzzle.grid, placed:puzzle.placed, cellEls:cellEls, board:board, found:0, dragging:false, start:null, path:[]};
    wireSopaPointer();
  }
  function buildWordSearch(words, N){
    var grid=[]; for(var i=0;i<N;i++){ grid[i]=[]; for(var j=0;j<N;j++) grid[i][j]=''; }
    var placed=[]; var dirs=[[0,1],[1,0],[1,1],[1,-1]];
    words.forEach(function(word){
      if(word.length>N) return; var ok=false;
      for(var attempt=0; attempt<80 && !ok; attempt++){
        var w=(Math.random()<0.4)?word.split('').reverse().join(''):word;
        var d=dirs[(Math.random()*dirs.length)|0], dr=d[0], dc=d[1], len=w.length;
        var rStart = dr>0?randInt(0,N-len):randInt(0,N-1);
        var cStart = dc>0?randInt(0,N-len):(dc<0?randInt(len-1,N-1):randInt(0,N-1));
        var cells=[], good=true;
        for(var k=0;k<len;k++){ var rr=rStart+dr*k, cc=cStart+dc*k; if(rr<0||rr>=N||cc<0||cc>=N){good=false;break;} var ex=grid[rr][cc]; if(ex && ex!==w[k]){good=false;break;} cells.push([rr,cc]); }
        if(good){ for(var m=0;m<len;m++) grid[cells[m][0]][cells[m][1]]=w[m]; placed.push({word:word, cells:cells, found:false}); ok=true; }
      }
    });
    var letters=[]; placed.forEach(function(p){ p.cells.forEach(function(cc){ letters.push(grid[cc[0]][cc[1]]); }); });
    if(!letters.length) letters='AEIOURLNSTMCDP'.split('');
    for(var r=0;r<N;r++) for(var c=0;c<N;c++){ if(!grid[r][c]) grid[r][c]=letters[(Math.random()*letters.length)|0]; }
    return {grid:grid, placed:placed};
  }
  function cellFromPoint(x,y){ var el=document.elementFromPoint(x,y); if(!el) return null; el=el.closest? el.closest('.ag-cell'):null; if(!el) return null; return {r:+el.dataset.r, c:+el.dataset.c}; }
  function linePath(a,b){ var dr=b.r-a.r, dc=b.c-a.c; if(!(dr===0||dc===0||Math.abs(dr)===Math.abs(dc))) return null; var steps=Math.max(Math.abs(dr),Math.abs(dc)); var sr=Math.sign(dr), sc=Math.sign(dc); var p=[]; for(var i=0;i<=steps;i++) p.push([a.r+sr*i, a.c+sc*i]); return p; }
  function clearSel(){ var s=sopaState; if(!s) return; s.cellEls.forEach(function(row){ row.forEach(function(d){ d.classList.remove('ag-sel'); }); }); }
  function paintSel(path){ clearSel(); var s=sopaState; path.forEach(function(rc){ var d=s.cellEls[rc[0]] && s.cellEls[rc[0]][rc[1]]; if(d) d.classList.add('ag-sel'); }); }
  function sameCells(p, cells){ if(p.length!==cells.length) return false; var set={}; cells.forEach(function(c){ set[c[0]+'_'+c[1]]=1; }); for(var i=0;i<p.length;i++){ if(!set[p[i][0]+'_'+p[i][1]]) return false; } return true; }
  function wireSopaPointer(){
    var s=sopaState, b=s.board;
    function down(e){ var rc=cellFromPoint(e.clientX,e.clientY); if(!rc) return; s.dragging=true; s.start=rc; s.path=[[rc.r,rc.c]]; paintSel(s.path); try{ b.setPointerCapture(e.pointerId); }catch(err){} e.preventDefault(); }
    function move(e){ if(!s.dragging) return; var rc=cellFromPoint(e.clientX,e.clientY); if(!rc) return; var p=linePath(s.start,rc); if(p){ s.path=p; paintSel(p); } e.preventDefault(); }
    function up(e){ if(!s.dragging) return; s.dragging=false; resolveSel(); clearSel(); }
    b.addEventListener('pointerdown',down); b.addEventListener('pointermove',move);
    b.addEventListener('pointerup',up); b.addEventListener('pointercancel',up);
    s._down=down; s._move=move; s._up=up;
  }
  function resolveSel(){
    var s=sopaState; if(!s||!s.path.length) return;
    for(var i=0;i<s.placed.length;i++){ var p=s.placed[i]; if(p.found) continue;
      if(sameCells(s.path, p.cells)){
        p.found=true; s.found++;
        p.cells.forEach(function(rc){ var d=s.cellEls[rc[0]][rc[1]]; d.classList.add('ag-found'); d.style.background=p.color; });
        var chip=document.querySelector('#agWords .ag-wchip[data-word="'+p.word+'"]'); if(chip){ chip.classList.add('ag-lit'); chip.style.setProperty('--lc', p.color); }
        sound('module');
        if(s.found>=s.placed.length){ setTimeout(function(){ showResult(s.wid, s.conf, 'sopa', 'Encontraste '+s.placed.length+' palabras'); }, 420); }
        return;
      }
    }
  }

  /* ====================================================
     JUEGO 2 · MEMORIA (parejas)
     ==================================================== */
  var memState=null;
  function memImages(wid, pairs){
    var list=caps(wid).filter(function(c){ return !!img(c.id); }).map(function(c){ return {id:c.id, src:img(c.id), label:c.t}; });
    if(list.length<pairs && img(wid)) list.push({id:wid, src:img(wid), label:(wById(wid)||{}).n});
    shuffle(list); return list.slice(0, Math.max(3, Math.min(pairs, list.length)));
  }
  function startMemoria(wid, conf){
    teardownGame(); view='game'; ctx.game='memoria'; ctx.world=wid;
    var w=wById(wid)||{};
    var imgs=memImages(wid, conf.pairs);
    if(imgs.length<3){ say('Este mundo aún no tiene suficientes imágenes.'); showPicker('memoria'); return; }
    var deck=[]; imgs.forEach(function(it,i){ deck.push({pid:i,src:it.src,label:it.label}); deck.push({pid:i,src:it.src,label:it.label}); });
    shuffle(deck);
    var n=deck.length, cols=(n<=12?4:(n<=16?4:5));
    setHead((w.n||'Mundo'),'Memoria · '+conf.n,true);
    var acc=w.col||'#7c6ffd';
    var h='<div class="ag-mem" style="--ag-acc:'+acc+';--cols:'+cols+'" id="agMem"></div><div class="ag-mem-info" id="agMemInfo">Parejas: 0 / '+imgs.length+'</div>';
    body().innerHTML=h;
    var box=document.getElementById('agMem');
    deck.forEach(function(card,idx){
      var el=document.createElement('button'); el.className='ag-mem-card'; el.dataset.idx=idx; el.dataset.pid=card.pid; el.type='button';
      el.innerHTML='<span class="ag-mem-inner"><span class="ag-mem-back">'+(w.ico||'❓')+'</span><span class="ag-mem-front"><img src="'+card.src+'" alt="" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'grid\';"><b class="ag-mem-fallback">'+String(card.label||'Cápsula').replace(/[&<>]/g,function(ch){return {"&":"&amp;","<":"&lt;",">":"&gt;"}[ch];})+'</b></span></span>';
      box.appendChild(el);
    });
    memState={wid:wid, conf:conf, pairs:imgs.length, matched:0, first:null, lock:false, box:box};
    box.addEventListener('click', memClick);
  }
  function memClick(e){
    var s=memState; if(!s||s.lock) return; var card=e.target.closest? e.target.closest('.ag-mem-card'):null; if(!card) return;
    if(card.classList.contains('ag-flip')||card.classList.contains('ag-matched')) return;
    card.classList.add('ag-flip'); sound('module');
    if(!s.first){ s.first=card; return; }
    var a=s.first, b=card; s.first=null;
    if(a.dataset.pid===b.dataset.pid){ a.classList.add('ag-matched'); b.classList.add('ag-matched'); s.matched++; updateMemInfo();
      if(s.matched>=s.pairs){ setTimeout(function(){ showResult(s.wid,s.conf,'memoria','Hiciste '+s.pairs+' parejas'); },420); }
    } else { s.lock=true; setTimeout(function(){ a.classList.remove('ag-flip'); b.classList.remove('ag-flip'); s.lock=false; }, 760); }
  }
  function updateMemInfo(){ var s=memState; var el=document.getElementById('agMemInfo'); if(el) el.textContent='Parejas: '+s.matched+' / '+s.pairs; }

  /* ---------- limpieza ---------- */
  function teardownGame(){ sopaState=null; memState=null; rompeState=null; buscaState=null; }

  function GAMELABEL(g){ return g==='sopa'?'la sopa':(g==='memoria'?'la memoria':(g==='rompe'?'el rompecabezas':'la búsqueda')); }

  /* ====================================================
     JUEGO 3 · ROMPECABEZAS (tap-swap, 8/16/32)
     ==================================================== */
  var rompeState=null;
  function puzzleImage(wid){
    var pool=[]; var cv=img(wid); if(cv) pool.push(cv);
    caps(wid).forEach(function(c){ var s=img(c.id); if(s) pool.push(s); });
    if(!pool.length) return null;
    return pool[(Math.random()*pool.length)|0];
  }
  function isSolved(order){ for(var i=0;i<order.length;i++){ if(order[i]!==i) return false; } return true; }
  function startRompe(wid, conf){
    teardownGame(); view='game'; ctx.game='rompe'; ctx.world=wid;
    var w=wById(wid)||{}; var src=puzzleImage(wid);
    if(!src){ say('Este mundo aún no tiene imágenes.'); showPicker('rompe'); return; }
    var rows=conf.rows, cols=conf.cols, n=rows*cols;
    var order=[]; for(var i=0;i<n;i++) order.push(i);
    do{ shuffle(order); }while(isSolved(order)); // que nunca empiece resuelto
    setHead((w.n||'Mundo'),'Rompecabezas · '+conf.n,true);
    var acc=w.col||'#7c6ffd';
    var h='<div class="ag-rompe" style="--ag-acc:'+acc+'">'
      +'<div class="ag-rompe-hint">Toca dos piezas para intercambiarlas</div>'
      +'<div class="ag-puzzle" id="agPuzzle" style="--rows:'+rows+';--cols:'+cols+';aspect-ratio:'+cols+'/'+rows+'"></div>'
      +'<button class="ag-btn ag-btn-2 ag-peek" id="agPeek" type="button">👁️ Ver imagen</button>'
      +'<div class="ag-peekimg" id="agPeekImg"><img src="'+src+'" alt=""></div>'
      +'</div>';
    body().innerHTML=h;
    var box=document.getElementById('agPuzzle');
    rompeState={wid:wid, conf:conf, rows:rows, cols:cols, n:n, src:src, order:order, sel:-1, box:box};
    renderPuzzle();
    box.addEventListener('click', rompeClick);
    var peek=document.getElementById('agPeek'), pi=document.getElementById('agPeekImg');
    peek.addEventListener('click',function(){ pi.classList.toggle('ag-show'); });
  }
  function renderPuzzle(){
    var s=rompeState; if(!s) return; var box=s.box; box.innerHTML='';
    for(var slot=0; slot<s.n; slot++){
      var piece=s.order[slot];
      var pr=Math.floor(piece/s.cols), pc=piece%s.cols;
      var el=document.createElement('div'); el.className='ag-piece'; el.dataset.slot=slot;
      el.style.backgroundImage='url('+s.src+')';
      el.style.backgroundSize=(s.cols*100)+'% '+(s.rows*100)+'%';
      el.style.backgroundPosition=(s.cols>1?(pc*100/(s.cols-1)):0)+'% '+(s.rows>1?(pr*100/(s.rows-1)):0)+'%';
      if(slot===s.sel) el.classList.add('ag-piece-sel');
      box.appendChild(el);
    }
  }
  function rompeClick(e){
    var s=rompeState; if(!s) return; var el=e.target.closest? e.target.closest('.ag-piece'):null; if(!el) return;
    var slot=+el.dataset.slot;
    if(s.sel===-1){ s.sel=slot; renderPuzzle(); return; }
    if(s.sel===slot){ s.sel=-1; renderPuzzle(); return; }
    var t=s.order[s.sel]; s.order[s.sel]=s.order[slot]; s.order[slot]=t; s.sel=-1;
    sound('module'); renderPuzzle();
    if(isSolved(s.order)){ setTimeout(function(){ showResult(s.wid, s.conf, 'rompe', 'Armaste '+s.n+' piezas'); }, 360); }
  }

  /* ====================================================
     JUEGO 4 · BUSCA Y ENCUENTRA (motor + escena DEMO)
     Escenas reales: define window.ATLAS_BUSCA_SCENES = {
       worldId: { img:'<url o dataURI>', targets:[
         {label:'una estrella', x:0.32, y:0.48, r:0.07}, ...
       ]}
     }  (x,y,r en fracción 0..1 sobre la imagen)
     ==================================================== */
  var buscaState=null;
  var buscaPointers = new Map();
  function buscaScene(wid){
    var defined = (typeof window!=='undefined' && window.ATLAS_BUSCA_SCENES) ? window.ATLAS_BUSCA_SCENES[wid] : null;
    if(defined && defined.img && defined.targets && defined.targets.length) return {scene:defined, demo:false};
    var cover=img(wid); if(!cover) return null;
    var demo={ img:cover, difficulty:{facil:3,medio:3,explorador:3}, targets:[
      {label:'arriba a la izquierda', x:0.22, y:0.24, r:0.10},
      {label:'el centro', x:0.50, y:0.52, r:0.10},
      {label:'abajo a la derecha', x:0.78, y:0.76, r:0.10}
    ]};
    return {scene:demo, demo:true};
  }
  function buscaDifficultyCount(scene,diff){
    var d=scene.difficulty||{};
    return Math.min(scene.targets.length, d[diff] || (diff==='facil'?5:diff==='medio'?7:scene.targets.length));
  }
  function buscaActiveIndexes(){
    var s=buscaState; if(!s) return [];
    var n=buscaDifficultyCount(s.scene,s.difficulty||'medio');
    return s.scene.targets.map(function(_,i){return i;}).slice(0,n);
  }
  function startBusca(wid){
    teardownGame(); view='game'; ctx.game='busca'; ctx.world=wid;
    var w=wById(wid)||{}; var got=buscaScene(wid);
    if(!got){ say('Este mundo aún no tiene escena.'); showPicker('busca'); return; }
    var scene=got.scene, demo=got.demo;
    setHead((w.n||'Mundo'),'Busca y encuentra'+(demo?' · DEMO':''),true);
    var acc=w.col||'#7c6ffd';
    var h='<div class="ag-busca ag-busca-v61" style="--ag-acc:'+acc+'">'
      +(demo?'<div class="ag-demo-note">Escena de demostración. Este mundo aún no tiene coordenadas reales.</div>':'')
      +'<div class="ag-find-help"><b>🔎 Misión:</b> toca los objetos de la lista. La imagen inicia completa; usa +/−, rueda o dos dedos para acercar. Arrastra para moverte.</div>'
      +'<div class="ag-find-tools"><button data-diff="facil">Fácil · 5</button><button data-diff="medio">Medio · 7</button><button data-diff="explorador">Explorador · todo</button></div>'
      +'<div class="ag-find-list" id="agFindList"></div>'
      +'<div class="ag-find-toolbar"><button id="agZoomOut" type="button">−</button><button id="agZoomReset" type="button">100%</button><button id="agZoomIn" type="button">+</button><button id="agFitBtn" type="button">Ver completa</button><button id="agGridBtn" type="button">Rejilla</button></div>'
      +'<div class="ag-find-viewport" id="agFindWrap"><div class="ag-find-stage" id="agFindStage"><img class="ag-find-img" id="agFindImg" src="'+scene.img+'" alt="Escena busca y encuentra"><div class="ag-find-markers" id="agFindMarks"></div><div class="ag-find-grid" id="agFindGrid"></div></div></div>'
      +'<div class="ag-find-info" id="agFindInfo"></div>'
      +'</div>';
    body().innerHTML=h;
    buscaState={wid:wid, scene:scene, demo:demo, found:[], total:0, difficulty:'medio', scale:1, fitScale:1, tx:0, ty:0, dragging:false, moved:false, startX:0, startY:0, baseX:0, baseY:0, pinchStart:0, pinchScale:1, pinchMid:null, grid:false};
    buscaPointers = new Map();
    buscaRenderList(); buscaBindEvents();
    var im=document.getElementById('agFindImg');
    if(im){ if(im.complete) buscaFitImage(); else im.addEventListener('load',buscaFitImage,{once:true}); }
    else buscaApplyTransform();
  }
  function buscaRenderList(){
    var s=buscaState; if(!s) return;
    var list=document.getElementById('agFindList'); var info=document.getElementById('agFindInfo'); var marks=document.getElementById('agFindMarks');
    var active=buscaActiveIndexes(); s.total=active.length;
    if(list) list.innerHTML=active.map(function(i){ var t=s.scene.targets[i]; return '<span class="ag-find-chip '+(s.found.indexOf(i)>=0?'ag-lit':'')+'" data-i="'+i+'">'+t.label+'</span>'; }).join('');
    if(info) info.textContent='Encontrados: '+s.found.length+' / '+s.total+' · dificultad: '+(s.difficulty==='facil'?'Fácil':s.difficulty==='medio'?'Medio':'Explorador');
    if(marks){ marks.innerHTML=''; s.found.forEach(function(i){ var t=s.scene.targets[i]; if(t) buscaAddMarker(t); }); }
    document.querySelectorAll('.ag-find-tools button').forEach(function(b){ b.classList.toggle('on', b.dataset.diff===s.difficulty); });
  }
  function setBuscaDifficulty(diff){
    var s=buscaState; if(!s) return;
    s.difficulty=diff; s.found=[]; buscaRenderList(); sound('module');
  }
  function buscaClampPan(){
    var s=buscaState; if(!s) return;
    var wrap=document.getElementById('agFindWrap'), stage=document.getElementById('agFindStage'); if(!wrap||!stage) return;
    var wr=wrap.getBoundingClientRect();
    var bw=stage.offsetWidth||wr.width, bh=stage.offsetHeight||wr.height;
    var sw=bw*s.scale, sh=bh*s.scale;
    var maxX=Math.max(0,(sw-wr.width)/2)+18;
    var maxY=Math.max(0,(sh-wr.height)/2)+18;
    s.tx=Math.max(-maxX,Math.min(maxX,s.tx));
    s.ty=Math.max(-maxY,Math.min(maxY,s.ty));
  }
  function buscaApplyTransform(){
    var s=buscaState; if(!s) return;
    var stage=document.getElementById('agFindStage'); if(!stage) return;
    buscaClampPan();
    stage.style.transform='translate('+s.tx+'px,'+s.ty+'px) scale('+s.scale+')';
    var zr=document.getElementById('agZoomReset'); if(zr) zr.textContent=Math.round(s.scale*100)+'%';
  }
  function buscaFitImage(){
    var s=buscaState; if(!s) return;
    s.fitScale=1; s.scale=1; s.tx=0; s.ty=0; buscaApplyTransform();
  }
  function buscaZoom(delta, cx, cy){
    var s=buscaState; if(!s) return;
    var old=s.scale, min=1, max=3.2;
    var next=Math.max(min, Math.min(max, old*delta));
    if(Math.abs(next-old)<0.001) return;
    if(cx!==undefined && cy!==undefined){
      var wrap=document.getElementById('agFindWrap'); var r=wrap?wrap.getBoundingClientRect():null;
      if(r){
        var ox=cx-(r.left+r.width/2)-s.tx, oy=cy-(r.top+r.height/2)-s.ty;
        var ratio=next/old;
        s.tx=s.tx-ox*(ratio-1); s.ty=s.ty-oy*(ratio-1);
      }
    }else{
      var ratio=next/old; s.tx*=ratio; s.ty*=ratio;
    }
    s.scale=next; buscaApplyTransform();
  }
  function buscaResetZoom(){ buscaFitImage(); }
  function buscaToggleGrid(){ var s=buscaState; if(!s) return; s.grid=!s.grid; var g=document.getElementById('agFindGrid'); if(g) g.classList.toggle('on',s.grid); }
  function buscaBindEvents(){
    var wrap=document.getElementById('agFindWrap'); if(!wrap) return;
    wrap.addEventListener('click', buscaClick);
    wrap.addEventListener('wheel', function(e){ e.preventDefault(); buscaZoom(e.deltaY<0?1.12:0.89,e.clientX,e.clientY); }, {passive:false});
    wrap.addEventListener('pointerdown', function(e){ var s=buscaState; if(!s) return; buscaPointers.set(e.pointerId,{x:e.clientX,y:e.clientY}); s.moved=false; if(buscaPointers.size===1){ s.dragging=true; s.startX=e.clientX; s.startY=e.clientY; s.baseX=s.tx; s.baseY=s.ty; } if(buscaPointers.size===2){ var a=Array.from(buscaPointers.values()); s.pinchStart=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y); s.pinchScale=s.scale; } wrap.setPointerCapture?.(e.pointerId); });
    wrap.addEventListener('pointermove', function(e){ var s=buscaState; if(!s || !buscaPointers.has(e.pointerId)) return; buscaPointers.set(e.pointerId,{x:e.clientX,y:e.clientY}); if(buscaPointers.size===2){ var a=Array.from(buscaPointers.values()); var dist=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y); if(s.pinchStart){ s.scale=Math.max(1,Math.min(3.2,s.pinchScale*(dist/s.pinchStart))); buscaApplyTransform(); s.moved=true; } return; } if(s.dragging && s.scale>1.002){ var dx=e.clientX-s.startX, dy=e.clientY-s.startY; if(Math.abs(dx)+Math.abs(dy)>5) s.moved=true; s.tx=s.baseX+dx; s.ty=s.baseY+dy; buscaApplyTransform(); } });
    function endPtr(e){ var s=buscaState; if(!s) return; buscaPointers.delete(e.pointerId); if(buscaPointers.size===0){ s.dragging=false; setTimeout(function(){ if(s) s.moved=false; },80); } }
    wrap.addEventListener('pointerup',endPtr); wrap.addEventListener('pointercancel',endPtr); wrap.addEventListener('pointerleave',function(e){ if(buscaPointers.size) endPtr(e); });
    document.querySelectorAll('.ag-find-tools button').forEach(function(b){ b.addEventListener('click',function(){ setBuscaDifficulty(b.dataset.diff); }); });
    document.getElementById('agZoomIn')?.addEventListener('click',function(){ buscaZoom(1.18); });
    document.getElementById('agZoomOut')?.addEventListener('click',function(){ buscaZoom(0.85); });
    document.getElementById('agZoomReset')?.addEventListener('click',buscaResetZoom);
    document.getElementById('agFitBtn')?.addEventListener('click',buscaFitImage);
    document.getElementById('agGridBtn')?.addEventListener('click',buscaToggleGrid);
    window.addEventListener('resize', buscaFitImage, {passive:true});
  }
  function buscaAddMarker(t){
    var marks=document.getElementById('agFindMarks'); if(!marks) return;
    var m=document.createElement('div'); m.className='ag-find-mark'; m.style.left=(t.x*100)+'%'; m.style.top=(t.y*100)+'%'; marks.appendChild(m);
  }
  function buscaClick(e){
    var s=buscaState; if(!s) return;
    if(s.moved) return;
    var imgEl=document.getElementById('agFindImg'); if(!imgEl) return; var rect=imgEl.getBoundingClientRect();
    var fx=(e.clientX-rect.left)/rect.width, fy=(e.clientY-rect.top)/rect.height;
    if(fx<0||fx>1||fy<0||fy>1) return;
    var active=buscaActiveIndexes();
    var best=null, bestDist=999;
    for(var k=0;k<active.length;k++){
      var i=active[k]; if(s.found.indexOf(i)>=0) continue;
      var t=s.scene.targets[i]; var dx=fx-t.x, dy=fy-t.y; var dist=Math.sqrt(dx*dx+dy*dy);
      var pixelRadius=Math.max(42, Math.min(96, rect.width*(t.r||0.08)*1.45));
      var normRadius=pixelRadius/rect.width;
      if(dist<=normRadius && dist<bestDist){ best={i:i,t:t}; bestDist=dist; }
    }
    if(best){
      var i=best.i, t=best.t;
      s.found.push(i); sound('module'); buscaAddMarker(t);
      var chip=document.querySelector('.ag-find-chip[data-i="'+i+'"]'); if(chip) chip.classList.add('ag-lit');
      buscaRenderList();
      if(s.found.length>=s.total){ setTimeout(function(){ showResult(s.wid, {k:s.demo?'demo':'real', n:'Búsqueda', xp:40, coins:8}, 'busca', 'Encontraste '+s.total+' cosas'); }, 380); }
      return;
    }
    say('¡Sigue buscando! Puedes tocar cerca del objeto; usa + para acercar si está muy pequeño.');
  }
  window.setBuscaDifficulty=setBuscaDifficulty;
  window.buscaResetZoom=buscaResetZoom;
  window.buscaToggleGrid=buscaToggleGrid;
  /* ---------- lanzador (FAB) ---------- */
  function addFab(){
    if(document.getElementById('agFab')) return;
    var b=document.createElement('button'); b.id='agFab'; b.className='ag-fab'; b.type='button'; b.setAttribute('aria-label','Juegos');
    b.innerHTML='<span class="ag-fab-ico">🎮</span>';
    b.addEventListener('click',open);
    document.body.appendChild(b);
  }
  window.openAtlasGames=open;
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',function(){ setTimeout(addFab,80); });
  else setTimeout(addFab,80);
})();

