/* v63 · Libros integrados + pantallas de premios/certificados + UX móvil + juegos robustos */
(function atlasV63(){
  function safeV63(v){
    return String(v ?? '').replace(/[&<>"']/g, function(ch){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[ch]; });
  }
  function stripCloseButtonV63(html){
    return String(html || '').replace(/<button\b[^>]*class=["'][^"']*close-x[^"']*["'][\s\S]*?<\/button>/i,'').trim();
  }

  /* 1. Integración de imágenes de “Libros que Cambiaron Mundos” sin tocar títulos. */
  try{
    var litBase = 'assets/mundos/libros-que-cambiaron-mundos/';
    var litImages = {
      literature: litBase + 'mundo_libros-que-cambiaron-mundos.png',
      literature01: litBase + 'libros_01_mil_noches.png',
      literature02: litBase + 'libros_02_grimm_recolectores.png',
      literature03: litBase + 'libros_03_pombo_jugueton.png',
      literature04: litBase + 'libros_04_verne_viajero.png',
      literature05: litBase + 'libros_05_submarino_nautilus.png',
      literature06: litBase + 'libros_06_centro_terrestre.png',
      literature07: litBase + 'libros_07_frankenstein_despierta.png',
      literature08: litBase + 'libros_08_macondo_nace.png',
      literature09: litBase + 'libros_09_nobel_colombiano.png',
      literature10: litBase + 'libros_10_pedro_paramo.png',
      literature11: litBase + 'libros_11_alicia_cae.png',
      literature12: litBase + 'libros_12_hobbit_pequeno.png',
      literature13: litBase + 'libros_13_anillo_peligroso.png',
      literature14: litBase + 'libros_14_diario_escondido.png',
      literature15: litBase + 'libros_15_don_quijote.png',
      literature16: litBase + 'libros_16_principito_viajero.png',
      literature17: litBase + 'libros_17_panchatantra_antiguo.png',
      literature18: litBase + 'libros_18_fabulas_de_esopo.png',
      literature19: litBase + 'libros_19_nobel_literario.png',
      literature20: litBase + 'libros_20_libros_viajeros.png',
      literature_bonus: litBase + 'libros_regalo_sutra_impreso.png',
      literaturebonus: litBase + 'libros_regalo_sutra_impreso.png'
    };
    window.ATLAS_IMG = Object.assign(window.ATLAS_IMG || {}, litImages);
    try{ if(typeof ATLAS_IMG !== 'undefined') Object.assign(ATLAS_IMG, litImages); }catch(e){}
    try{
      if(typeof WORLDS !== 'undefined') WORLDS.forEach(function(w){ if(window.ATLAS_IMG[w.id]) w.img = window.ATLAS_IMG[w.id]; });
      if(typeof CAPSULES !== 'undefined') CAPSULES.forEach(function(c){ if(window.ATLAS_IMG[c.id]) c.img = window.ATLAS_IMG[c.id]; });
    }catch(e){}
  }catch(e){ try{ console.warn('v63 literature images', e); }catch(_){} }

  /* 2. Modal con “← Atrás” real y “✕” para cerrar todo. */
  try{
    var nativeCloseOverlayV63 = (typeof closeOverlay === 'function') ? closeOverlay : null;
    var modalStackV63 = [];
    var currentModalV63 = '';
    function paintModalV63(html, replace){
      var overlay = document.getElementById('modalOverlay');
      var box = document.getElementById('modalBox');
      if(!box || !overlay) return;
      var clean = stripCloseButtonV63(html);
      if(!replace && currentModalV63 && !overlay.classList.contains('hidden')) modalStackV63.push(currentModalV63);
      currentModalV63 = clean;
      var back = modalStackV63.length ? '<button class="modal-back-v63" type="button" onclick="atlasModalBackV63()">← Atrás</button>' : '<span class="modal-spacer-v63"></span>';
      box.innerHTML = '<div class="modal-nav-v63">' + back + '<button class="close-x modal-close-v63" type="button" onclick="closeOverlay(\'modalOverlay\')">✕</button></div>' + clean;
      overlay.classList.remove('hidden');
    }
    window.atlasModalBackV63 = function(){
      if(modalStackV63.length){
        var prev = modalStackV63.pop();
        paintModalV63(prev, true);
      }else if(typeof closeOverlay === 'function'){
        closeOverlay('modalOverlay');
      }
    };
    window.openModal = openModal = function(html, opts){
      paintModalV63(html, !!(opts && opts.replace));
    };
    window.closeOverlay = closeOverlay = function(id){
      if(id === 'modalOverlay'){
        modalStackV63 = [];
        currentModalV63 = '';
      }
      if(nativeCloseOverlayV63) nativeCloseOverlayV63(id);
      else { var el=document.getElementById(id); if(el) el.classList.add('hidden'); }
    };
  }catch(e){ try{ console.warn('v63 modal stack', e); }catch(_){} }

  function ensureGalleryScreensV63(){
    if(document.getElementById('trophyRoomScreen')) return;
    var modal = document.getElementById('modalOverlay');
    if(!modal || !modal.parentNode) return;
    modal.insertAdjacentHTML('beforebegin',
      '<section id="trophyRoomScreen" class="screen atlas-room-screen trophy-room-screen">' +
        '<div class="particles room-particles" id="trophyParticles"></div>' +
        '<header class="room-topbar"><button class="icon-btn" onclick="showScreen(\'homeScreen\'); updateHome?.();">←</button><div><span class="kicker">Premios</span><h2>🏅 Sala de Trofeos</h2><p>Logros y medallas reunidos en una sola vitrina.</p></div><button class="secondary" onclick="renderCertificates()">📜 Certificados</button></header>' +
        '<main id="trophyRoomBody" class="room-main"></main>' +
      '</section>' +
      '<section id="certGalleryScreen" class="screen atlas-room-screen cert-gallery-screen">' +
        '<div class="particles room-particles" id="certParticles"></div>' +
        '<header class="room-topbar"><button class="icon-btn" onclick="showScreen(\'homeScreen\'); updateHome?.();">←</button><div><span class="kicker">Galería</span><h2>📜 Certificados</h2><p>Diplomas del Atlas listos para ver o descargar.</p></div><button class="secondary" onclick="renderAwardsHub()">🏅 Trofeos</button></header>' +
        '<main id="certGalleryBody" class="room-main"></main>' +
      '</section>'
    );
    try{ makeParticles('trophyParticles',70); makeParticles('certParticles',70); }catch(e){}
  }

  function drawRingV63(percent, label, icon){
    var p = Math.max(0, Math.min(100, Math.round(percent || 0)));
    return '<div class="progress-orb-v63" style="--p:' + p + '"><div><span>' + safeV63(icon || '✨') + '</span><b>' + p + '%</b><small>' + safeV63(label || 'avance') + '</small></div></div>';
  }

  /* 3. Logros/medallas como pantalla propia. */
  window.renderAwardsHub = renderAwardsHub = function(){
    ensureGalleryScreensV63();
    try{ checkBadges(); saveState(); }catch(e){}
    var defs = (typeof badgeDefinitions === 'function') ? badgeDefinitions() : [];
    var unlocked = defs.filter(function(b){ return U && U.badges && U.badges.includes(b.id); });
    var medals = defs.filter(function(b){ return (b.type || (String(b.id).includes('atlas') || String(b.id).includes('world') ? 'medalla' : 'logro')) === 'medalla'; });
    var achievements = defs.filter(function(b){ return !medals.includes(b); });
    var body = document.getElementById('trophyRoomBody');
    if(!body) return;
    function card(b, i){
      var got = U && U.badges && U.badges.includes(b.id);
      return '<article class="trophy-card-v63 ' + (got?'is-earned':'is-locked') + '" style="--i:' + i + '">' +
        '<div class="trophy-shine-v63"></div><div class="trophy-ico-v63">' + (got ? safeV63(b.ico) : '🔒') + '</div>' +
        '<span class="pill">' + (got ? 'obtenido' : 'pendiente') + '</span>' +
        '<h3>' + safeV63(b.n) + '</h3><p>' + safeV63(b.desc) + '</p>' +
      '</article>';
    }
    body.innerHTML =
      '<section class="room-hero-v63 trophy-hero-v63">' +
        drawRingV63(defs.length ? unlocked.length / defs.length * 100 : 0, 'trofeos', '🏆') +
        '<div><span class="kicker">Vitrina del explorador</span><h3>' + unlocked.length + ' de ' + defs.length + ' premios obtenidos</h3><p>Cada tarjeta explorada, regalo abierto, quiz y mundo completado deja una huella en esta sala.</p></div>' +
      '</section>' +
      '<div class="room-tabs-v63"><a href="#logrosV63">🌟 Logros</a><a href="#medallasV63">🏅 Medallas</a></div>' +
      '<section id="logrosV63" class="room-section-v63"><h3>🌟 Logros</h3><div class="trophy-grid-v63">' + achievements.map(card).join('') + '</div></section>' +
      '<section id="medallasV63" class="room-section-v63"><h3>🏅 Medallas</h3><div class="trophy-grid-v63">' + medals.map(card).join('') + '</div></section>';
    showScreen('trophyRoomScreen');
    try{ confetti(18); playSound('module'); }catch(e){}
  };
  window.renderAchievements = renderAchievements = function(){ renderAwardsHub(); };

  /* 4. Certificados como Galería propia. */
  window.renderCertificates = renderCertificates = function(){
    ensureGalleryScreensV63();
    var st = (typeof certificateStats === 'function') ? certificateStats() : {items:[], earned:[]};
    var items = st.items || [];
    var earned = items.filter(function(c){ return c.score >= 80; });
    var body = document.getElementById('certGalleryBody');
    if(!body) return;
    function certCard(c, i){
      var ready = c.score >= 80;
      return '<article class="cert-diploma-v63 ' + (ready?'is-earned':'is-locked') + '" style="--i:' + i + '">' +
        '<div class="cert-ribbon-v63">' + (ready ? safeV63(c.ico) : '🔒') + '</div>' +
        '<div class="cert-copy-v63"><span class="pill">' + (ready ? 'listo' : 'avance') + '</span><h3>' + safeV63(c.n) + '</h3><p>' + safeV63(c.desc) + '</p>' +
        '<div class="cert-meter"><i style="width:' + Math.max(0, Math.min(100, c.score)) + '%"></i></div><small>' + c.score + '%</small></div>' +
        (ready ? '<div class="cert-actions-v45"><button class="cert-download" onclick="window.downloadCertificateHTML(\'' + c.id + '\')">⬇️ HTML</button><button class="cert-download alt" onclick="window.openCertificateHTML(\'' + c.id + '\')">👀 Vista</button></div>' : '<button class="cert-download is-disabled" disabled>🔒 Aún no disponible</button>') +
      '</article>';
    }
    body.innerHTML =
      '<section class="room-hero-v63 cert-hero-v63">' +
        drawRingV63(items.length ? earned.length / items.length * 100 : 0, 'certificados', '📜') +
        '<div><span class="kicker">Galería de diplomas</span><h3>' + earned.length + ' certificados listos</h3><p>Cuando un certificado alcanza 80%, puedes abrir la vista o descargarlo en HTML para imprimirlo.</p></div>' +
      '</section>' +
      '<div class="cert-shelf-v63">' + items.map(certCard).join('') + '</div>';
    showScreen('certGalleryScreen');
    try{ playSound('module'); }catch(e){}
  };

  /* 5. “Adelante” en pantalla inicial sin tocar otros títulos/frases. */
  try{
    var originalUpdateTopV63 = (typeof updateTop === 'function') ? updateTop : null;
    if(originalUpdateTopV63){
      window.updateTop = updateTop = function(){
        originalUpdateTopV63();
        try{
          var title = document.getElementById('homeTitle');
          if(title && U && U.seen && U.seen.length) title.textContent = 'Adelante, ' + (U.name || 'Explorador');
        }catch(e){}
      };
    }
  }catch(e){}

  /* 6. Dock móvil: pista visual de desplazamiento y recuerdo tras primer gesto. */
  function setupDockHintV63(){
    var dock = document.querySelector('.icon-dock');
    if(!dock || dock.dataset.v63Ready) return;
    dock.dataset.v63Ready = '1';
    function refresh(){ dock.classList.toggle('has-more-v63', dock.scrollWidth - dock.clientWidth - dock.scrollLeft > 8); }
    dock.addEventListener('scroll', function(){ dock.classList.add('has-touched-v63'); refresh(); }, {passive:true});
    window.addEventListener('resize', refresh);
    setTimeout(refresh, 180);
  }
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', setupDockHintV63);
  else setupDockHintV63();

  /* 7. Compra y apertura robusta de juegos premium. */
  try{
    var V63_GAME_META = {
      conecta_asombro:{id:'conecta_asombro', ico:'🧩', name:'Conecta el Asombro', tag:'relaciona pistas', why:'Une pistas y respuestas de cada mundo para reforzar comprensión.', price:250},
      memoria_mundos:{id:'memoria_mundos', ico:'🧠', name:'Memoria de Mundos', tag:'memoria visual', why:'Encuentra parejas entre mundos, iconos y conceptos del Atlas.', price:320}
    };
    function ensureGamesV63(){ if(!U) return; if(!Array.isArray(U.premiumGames)) U.premiumGames = []; if(!U.premiumGameRuns) U.premiumGameRuns = {}; }
    function gameOwnedV63(id){ ensureGamesV63(); return !!(U && U.premiumGames && U.premiumGames.includes(id)); }
    window.buyPremiumGame = function(id){
      ensureGamesV63();
      var g = V63_GAME_META[id];
      if(!g){ toast('Juego no encontrado.'); return; }
      if(gameOwnedV63(id)){ toast(g.name + ' ya está desbloqueado.'); if(window.openPremiumGamePicker) window.openPremiumGamePicker(id); return; }
      var coins = U.coins || 0;
      if(coins < g.price){ toast('Necesitas ' + (g.price - coins) + ' monedas más para desbloquear ' + g.name + '.', 3400); return; }
      U.coins = coins - g.price;
      U.premiumGames.push(id);
      try{ saveState(); updateTop(); renderWorlds(); }catch(e){}
      toast('¡' + g.name + ' desbloqueado!');
      try{ confetti(70); playSound('gift'); }catch(e){}
      if(window.openPremiumGamePicker) setTimeout(function(){ window.openPremiumGamePicker(id); }, 160);
    };
    var originalPickerV63 = window.openPremiumGamePicker;
    window.openPremiumGamePicker = function(gameId){
      ensureGamesV63();
      var g = V63_GAME_META[gameId];
      if(!g){ toast('Juego no encontrado.'); return; }
      if(!gameOwnedV63(gameId)){
        if(window.openPremiumGamesHub) return window.openPremiumGamesHub();
        return renderShop ? renderShop() : toast('Compra el juego primero.');
      }
      if(gameId === 'memoria_mundos') return window.openPremiumDifficulty ? window.openPremiumDifficulty(gameId, null) : originalPickerV63 && originalPickerV63(gameId);
      var worlds = (typeof WORLDS !== 'undefined' ? WORLDS : []).filter(function(w){ return typeof worldUnlocked !== 'function' || worldUnlocked(w.id); });
      if(!worlds.length) worlds = (typeof WORLDS !== 'undefined' ? WORLDS : []);
      var html = worlds.map(function(w){
        var cover = (typeof ATLAS_IMG !== 'undefined' && ATLAS_IMG[w.id]) ? ATLAS_IMG[w.id] : '';
        return '<button class="pg-world" onclick="openPremiumDifficulty(\'' + gameId + '\',\'' + w.id + '\')" style="--wc:' + safeV63(w.col || '#7c6ffd') + '">' +
          (cover ? '<img src="' + safeV63(cover) + '" alt="">' : '<span>' + safeV63(w.ico || '🌍') + '</span>') +
          '<b>' + safeV63(w.n) + '</b><small>' + safeV63(w.discipline || '') + '</small></button>';
      }).join('');
      openModal('<div class="premium-games-head"><span class="kicker">' + safeV63(g.name) + '</span><h2>' + safeV63(g.ico) + ' Elige un mundo</h2><p>Las pistas salen de las cápsulas del mundo elegido.</p></div><div class="pg-world-grid">' + html + '</div>');
      try{ playSound('module'); }catch(e){}
    };
  }catch(e){ try{ console.warn('v63 premium games', e); }catch(_){} }

  /* 8. Rebinding tardío para que los botones usen las pantallas v63 aun si init ya dejó handlers anteriores. */
  function rebindV63(){
    try{
      var a=document.getElementById('achievementsBtn'); if(a) a.onclick=renderAwardsHub;
      var c=document.getElementById('certificatesBtn'); if(c) c.onclick=renderCertificates;
      var n=document.getElementById('navAwards'); if(n) n.onclick=renderAwardsHub;
      setupDockHintV63();
      if(typeof updateTop === 'function') updateTop();
    }catch(e){}
  }
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', function(){ setTimeout(rebindV63, 320); });
  else setTimeout(rebindV63, 320);
})();

