/* v64 · refuerzo visual: cabecera sticky, volver visible y pantalla siempre arriba */
(function atlasV64(){
  function safeV64(v){return String(v ?? '').replace(/[&<>"']/g,function(ch){return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[ch];});}
  function goHomeV64(){
    try{ closeOverlay && closeOverlay('modalOverlay'); }catch(e){}
    try{ showScreen('homeScreen'); }catch(e){}
    try{ updateHome && updateHome(); updateTop && updateTop(); }catch(e){}
    try{ var h=document.getElementById('homeScreen'); if(h) h.scrollTo({top:0,left:0,behavior:'instant'}); }catch(e){ try{ var h2=document.getElementById('homeScreen'); if(h2) h2.scrollTop=0; }catch(_){} }
  }
  window.atlasRoomBackV64 = goHomeV64;
  function roomHeaderV64(kind){
    var isCert = kind === 'cert';
    return '<header class="room-topbar-v64 '+(isCert?'cert-top-v64':'trophy-top-v64')+'">'+
      '<button class="room-back-v64" type="button" onclick="atlasRoomBackV64()">← <span>Volver al Atlas</span></button>'+
      '<div class="room-title-v64"><div class="room-title-badge-v64">'+(isCert?'📜':'🏆')+'</div><div><span class="kicker">'+(isCert?'Galería viva':'Sala viva de premios')+'</span><h2>'+(isCert?'Galería de Certificados':'Sala de Trofeos')+'</h2><p>'+(isCert?'Diplomas para ver, descargar e imprimir cuando cada mundo alcanza su meta.':'Logros y medallas reunidos como una vitrina de exploración, avance y asombro.')+'</p></div></div>'+
      '<button class="room-switch-v64" type="button" onclick="'+(isCert?'renderAwardsHub()':'renderCertificates()')+'">'+(isCert?'🏅 Ver trofeos':'📜 Ver certificados')+'</button>'+
    '</header>';
  }
  function decorateRoomV64(kind){
    var screen = document.getElementById(kind === 'cert' ? 'certGalleryScreen' : 'trophyRoomScreen');
    if(!screen) return;
    screen.classList.add('v64-room-ready');
    var header = screen.querySelector('header.room-topbar, header.room-topbar-v64');
    if(header) header.outerHTML = roomHeaderV64(kind);
    var body = document.getElementById(kind === 'cert' ? 'certGalleryBody' : 'trophyRoomBody');
    if(body){
      var hero = body.querySelector('.room-hero-v63');
      if(hero) hero.classList.add('room-hero-v64');
      var oldIntro = body.querySelector('.room-welcome-v64');
      if(oldIntro) oldIntro.remove();
      var intro = document.createElement('div');
      intro.className = 'room-welcome-v64';
      intro.innerHTML = kind === 'cert'
        ? '<div><strong>Tu galería ahora respira más como un diploma de aventura.</strong><span>Arriba queda siempre el regreso; al bajar, la cabecera permanece visible.</span></div><em>🖋️</em>'
        : '<div><strong>Esta vitrina muestra el camino recorrido, no solo una lista.</strong><span>Arriba queda siempre el regreso; logros y medallas aparecen como piezas de colección.</span></div><em>✨</em>';
      if(hero) body.insertBefore(intro, hero); else body.insertBefore(intro, body.firstChild);
    }
    try{
      requestAnimationFrame(function(){
        screen.scrollTop = 0;
        if(screen.scrollTo) screen.scrollTo({top:0,left:0,behavior:'instant'});
      });
    }catch(e){ screen.scrollTop = 0; }
  }
  var prevAwardsV64 = window.renderAwardsHub;
  var prevCertsV64 = window.renderCertificates;
  if(typeof prevAwardsV64 === 'function'){
    window.renderAwardsHub = renderAwardsHub = function(){
      var r = prevAwardsV64.apply(this, arguments);
      decorateRoomV64('trophy');
      try{ var s=document.getElementById('trophyRoomScreen'); if(s) s.scrollTop=0; }catch(e){}
      return r;
    };
  }
  if(typeof prevCertsV64 === 'function'){
    window.renderCertificates = renderCertificates = function(){
      var r = prevCertsV64.apply(this, arguments);
      decorateRoomV64('cert');
      try{ var s=document.getElementById('certGalleryScreen'); if(s) s.scrollTop=0; }catch(e){}
      return r;
    };
  }
  function rebindV64(){
    try{ var a=document.getElementById('achievementsBtn'); if(a) a.onclick=window.renderAwardsHub; }catch(e){}
    try{ var c=document.getElementById('certificatesBtn'); if(c) c.onclick=window.renderCertificates; }catch(e){}
    try{ var n=document.getElementById('navAwards'); if(n) n.onclick=window.renderAwardsHub; }catch(e){}
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',function(){setTimeout(rebindV64,420);}); else setTimeout(rebindV64,420);
})();

/* v65 · Explorador Galáctico cálido: Logros y Certificados */
(function atlasV65(){
  function escV65(v){
    return String(v ?? '').replace(/[&<>"']/g,function(ch){return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[ch];});
  }
  function goHomeV65(){
    try{ if(typeof closeOverlay==='function') closeOverlay('modalOverlay'); }catch(e){}
    try{ if(typeof showScreen==='function') showScreen('homeScreen'); }catch(e){}
    try{ if(typeof updateHome==='function') updateHome(); if(typeof updateTop==='function') updateTop(); }catch(e){}
    try{ var h=document.getElementById('homeScreen'); if(h){ h.scrollTop=0; if(h.scrollTo) h.scrollTo({top:0,left:0,behavior:'instant'}); } }catch(e){}
  }
  window.atlasRoomBackV65 = goHomeV65;
  function ensureRoomsV65(){
    var modal = document.getElementById('modalOverlay');
    var parent = modal && modal.parentNode ? modal.parentNode : document.body;
    if(!document.getElementById('trophyRoomScreen')){
      parent.insertBefore(document.createRange().createContextualFragment('<section id="trophyRoomScreen" class="screen atlas-room-screen v65-room-screen v65-trophy-screen"><div class="particles room-particles" id="trophyParticlesV65"></div><main id="trophyRoomBody" class="v65-room-main"></main></section>'), modal || null);
      try{ if(typeof makeParticles==='function') makeParticles('trophyParticlesV65',70); }catch(e){}
    }
    if(!document.getElementById('certGalleryScreen')){
      parent.insertBefore(document.createRange().createContextualFragment('<section id="certGalleryScreen" class="screen atlas-room-screen v65-room-screen v65-cert-screen"><div class="particles room-particles" id="certParticlesV65"></div><main id="certGalleryBody" class="v65-room-main"></main></section>'), modal || null);
      try{ if(typeof makeParticles==='function') makeParticles('certParticlesV65',70); }catch(e){}
    }
    var trophy=document.getElementById('trophyRoomScreen');
    var cert=document.getElementById('certGalleryScreen');
    if(trophy){ trophy.className='screen atlas-room-screen v65-room-screen v65-trophy-screen'; if(!document.getElementById('trophyRoomBody')) trophy.insertAdjacentHTML('beforeend','<main id="trophyRoomBody" class="v65-room-main"></main>'); }
    if(cert){ cert.className='screen atlas-room-screen v65-room-screen v65-cert-screen'; if(!document.getElementById('certGalleryBody')) cert.insertAdjacentHTML('beforeend','<main id="certGalleryBody" class="v65-room-main"></main>'); }
  }
  function headerV65(kind){
    var cert = kind === 'cert';
    return '<header class="v65-topbar">'+
      '<button class="v65-back" type="button" onclick="atlasRoomBackV65()">← <span>Volver al Atlas</span></button>'+
      '<div class="v65-title-wrap"><div class="v65-title-icon">'+(cert?'📜':'🏆')+'</div><div><span class="v65-kicker">'+(cert?'Galería galáctica':'Explorador galáctico')+'</span><h2>'+(cert?'Galería de Certificados':'Sala de Trofeos')+'</h2><p>'+(cert?'Diplomas vivos: exporta HTML, mira e imprime.':'Logros y medallas como piezas de colección del Atlas.')+'</p></div></div>'+
      '<button class="v65-switch" type="button" onclick="'+(cert?'renderAwardsHub()':'renderCertificates()')+'">'+(cert?'🏅 Ver trofeos':'📜 Ver certificados')+'</button>'+
    '</header>';
  }
  function ringV65(percent,label,icon){
    var p=Math.max(0,Math.min(100,Math.round(percent||0)));
    return '<div class="v65-ring" style="--p:'+p+'"><div><span>'+escV65(icon||'✨')+'</span><b>'+p+'%</b><small>'+escV65(label||'avance')+'</small></div></div>';
  }
  function scrollRoomTopV65(id){
    try{
      var s=document.getElementById(id);
      if(!s) return;
      requestAnimationFrame(function(){ s.scrollTop=0; if(s.scrollTo) s.scrollTo({top:0,left:0,behavior:'instant'}); });
    }catch(e){}
  }
  function bindButtonsV65(){
    try{ var a=document.getElementById('achievementsBtn'); if(a) a.onclick=window.renderAwardsHub; }catch(e){}
    try{ var c=document.getElementById('certificatesBtn'); if(c) c.onclick=window.renderCertificates; }catch(e){}
    try{ var n=document.getElementById('navAwards'); if(n) n.onclick=window.renderAwardsHub; }catch(e){}
  }
  function statusChipV65(ok, lockedText){
    return '<span class="v65-chip '+(ok?'ready':'')+'">'+(ok?'¡LISTO!':escV65(lockedText||'Por descubrir'))+'</span>';
  }
  window.renderAwardsHub = renderAwardsHub = function(){
    ensureRoomsV65();
    try{ if(typeof checkBadges==='function') checkBadges(); if(typeof saveState==='function') saveState(); }catch(e){}
    var defs = (typeof badgeDefinitions==='function') ? badgeDefinitions() : [];
    var owned = (window.U && Array.isArray(U.badges)) ? U.badges : [];
    var unlocked = defs.filter(function(b){return owned.includes(b.id);});
    var medals = defs.filter(function(b){ return (b.type || '').toLowerCase()==='medalla'; });
    var achievements = defs.filter(function(b){ return !medals.includes(b); });
    var body = document.getElementById('trophyRoomBody');
    if(!body) return;
    function card(b,i){
      var got = owned.includes(b.id);
      var type = (b.type || 'logro').toLowerCase()==='medalla' ? 'Medalla' : 'Logro';
      return '<article class="v65-award-card '+(got?'is-earned':'is-locked')+'" style="--i:'+i+'">'+
        '<div class="v65-award-top"><div class="v65-big-ico">'+escV65(b.ico||'✨')+(got?'':'<span class="v65-lock-dot">🔒</span>')+'</div>'+
        '<div class="v65-card-copy"><div class="v65-chip-row">'+statusChipV65(got,'Pendiente')+'<span class="v65-chip kind">'+type+'</span></div><h4>'+escV65(b.n)+'</h4><p>'+escV65(b.desc)+'</p></div></div>'+
        '<div class="v65-card-foot"><div class="v65-sparkline"><i style="width:'+(got?100:34)+'%"></i></div><span>'+(got?'¡GENIAL!':'Sigue explorando')+'</span></div>'+
      '</article>';
    }
    body.innerHTML = headerV65('trophy')+
      '<section class="v65-hero">'+
        ringV65(defs.length ? unlocked.length/defs.length*100 : 0,'trofeos','🏆')+
        '<div class="v65-hero-copy"><span class="v65-kicker">Vitrina del explorador</span><h3>'+unlocked.length+' de '+defs.length+' premios obtenidos</h3><p>Esta sala no funciona como una lista: cada logro se muestra como una pieza ganada en el viaje por mundos, regalos, tarjetas, quiz y certificados.</p></div>'+
        '<div class="v65-mini-stats"><span class="v65-stat-pill">🌟 '+achievements.filter(function(b){return owned.includes(b.id);}).length+' logros</span><span class="v65-stat-pill">🏅 '+medals.filter(function(b){return owned.includes(b.id);}).length+' medallas</span><span class="v65-stat-pill">✨ Colección viva</span></div>'+
      '</section>'+
      '<nav class="v65-tabs"><a href="#logrosV65">🌟 Logros</a><a href="#medallasV65">🏅 Medallas</a></nav>'+
      '<section id="logrosV65" class="v65-section"><h3>🌟 Logros</h3><div class="v65-grid">'+(achievements.length?achievements.map(card).join(''):'<div class="v65-empty">Todavía no hay logros para mostrar.</div>')+'</div></section>'+
      '<section id="medallasV65" class="v65-section"><h3>🏅 Medallas</h3><div class="v65-grid">'+(medals.length?medals.map(function(b,i){return card(b,i+achievements.length);}).join(''):'<div class="v65-empty">Todavía no hay medallas para mostrar.</div>')+'</div></section>';
    try{ if(typeof showScreen==='function') showScreen('trophyRoomScreen'); }catch(e){}
    scrollRoomTopV65('trophyRoomScreen');
    try{ if(typeof playSound==='function') playSound('module'); }catch(e){}
  };
  window.renderAchievements = renderAchievements = function(){ return window.renderAwardsHub(); };
  window.renderCertificates = renderCertificates = function(){
    ensureRoomsV65();
    var st = (typeof certificateStats==='function') ? certificateStats() : {items:[],earned:[]};
    var items = (st.items||[]).slice();
    var earned = items.filter(function(c){return (c.score||0)>=80;});
    var body = document.getElementById('certGalleryBody');
    if(!body) return;
    function certCard(c,i){
      var score=Math.max(0,Math.min(100,Math.round(c.score||0)));
      var ready=score>=80;
      var kind=(c.kind==='global')?'Atlas':(c.kind==='quiz'?'Quiz':'Mundo');
      return '<article class="v65-cert-card '+(ready?'is-earned':'is-locked')+'" style="--i:'+i+'">'+
        '<div class="v65-cert-seal">'+escV65(c.ico||'📜')+(ready?'':'<span class="v65-lock-dot">🔒</span>')+'</div>'+
        '<div class="v65-card-copy"><div class="v65-chip-row">'+statusChipV65(ready,score+'%')+'<span class="v65-chip kind">'+kind+'</span></div><h4>'+escV65(c.n)+'</h4><p>'+escV65(c.desc)+'</p>'+
        '<div class="v65-cert-meter"><i style="width:'+score+'%"></i></div><div class="v65-card-foot"><span>'+score+'% completado</span><span>'+(ready?'¡GENIAL!':'Meta 80%')+'</span></div>'+
        '<div class="v65-cert-actions">'+(ready?'<button class="v65-btn download" type="button" onclick="downloadCertificateHTML(\''+escV65(c.id)+'\')">⬇️ Exportar HTML</button><button class="v65-btn ghost" type="button" onclick="openCertificateHTML(\''+escV65(c.id)+'\')">👁️ Ver diploma</button>':'<button class="v65-btn ghost" type="button" disabled>🔭 Sigue explorando</button>')+'</div></div>'+
      '</article>';
    }
    body.innerHTML = headerV65('cert')+
      '<section class="v65-hero">'+
        ringV65(items.length ? earned.length/items.length*100 : 0,'diplomas','📜')+
        '<div class="v65-hero-copy"><span class="v65-kicker">Pasaporte de descubrimientos</span><h3>'+earned.length+' de '+items.length+' certificados listos</h3><p>Cada diploma conserva su exportación principal en HTML, con vista previa e impresión desde el navegador.</p></div>'+
        '<div class="v65-mini-stats"><span class="v65-stat-pill">⬇️ Exportar HTML</span><span class="v65-stat-pill">👁️ Ver diploma</span><span class="v65-stat-pill">🎯 Meta 80%</span></div>'+
      '</section>'+
      '<section class="v65-section"><h3>📜 Certificados del Atlas</h3><div class="v65-cert-grid">'+(items.length?items.map(certCard).join(''):'<div class="v65-empty">Todavía no hay certificados para mostrar.</div>')+'</div></section>';
    try{ if(typeof showScreen==='function') showScreen('certGalleryScreen'); }catch(e){}
    scrollRoomTopV65('certGalleryScreen');
    try{ if(typeof playSound==='function') playSound('module'); }catch(e){}
  };
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',function(){setTimeout(bindButtonsV65,520);}); else setTimeout(bindButtonsV65,520);
})();


/* v66 · Certificados: Exportar HTML restaurado como acción principal; compactación visual en CSS. */
